const EMBED = {"index.html": "<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, user-scalable=no\">\n<meta name=\"theme-color\" content=\"#0f2a66\">\n<title>Wiesn Team Challenge</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bowlby+One&family=Figtree:wght@500;700;800&display=swap\" media=\"print\" onload=\"this.media='all'\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<div id=\"app\" aria-live=\"polite\"></div>\n<div id=\"layer\"></div>\n<div id=\"toast\" role=\"status\"></div>\n<div id=\"net\" class=\"net on\">offline</div>\n<script src=\"/games.js\"></script>\n<script src=\"/app.js\"></script>\n</body>\n</html>\n", "style.css": "/* Wiesn Team Challenge v4 – Bayerisches Rautenmuster, Lebkuchenherz-Etiketten, harte Schatten */\n:root {\n  --nacht: #0f2a66;\n  --himmel: #1f58c7;\n  --schaum: #fff8e6;\n  --bernstein: #ffb21a;\n  --tinte: #121b3a;\n  --rot: #e8433f;\n  --gruen: #2f9e5b;\n  --brezn: #7a3e14;\n  --grau: #5b6485;\n  --display: 'Bowlby One', 'Arial Rounded MT Bold', 'Trebuchet MS', system-ui, sans-serif;\n  --text: 'Figtree', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;\n  --r: 18px;\n  --rand: 3px solid var(--tinte);\n  --schatten: 0 5px 0 var(--tinte);\n}\n* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\nhtml, body { margin: 0; height: 100%; }\nbody {\n  background: var(--nacht); color: var(--tinte); font: 500 16px/1.4 var(--text);\n  overflow-x: hidden; touch-action: manipulation; -webkit-user-select: none; user-select: none;\n}\nbody::before {            /* Raute: Schachbrett um 45° gedreht */\n  content: ''; position: fixed; inset: -60%; z-index: -1; transform: rotate(45deg);\n  background: conic-gradient(rgba(255,255,255,.07) 25%, transparent 0 50%, rgba(255,255,255,.07) 0 75%, transparent 0) 0 0 / 84px 84px;\n}\n#app { min-height: 100%; max-width: 520px; margin: 0 auto; padding: calc(env(safe-area-inset-top) + 14px) 14px calc(env(safe-area-inset-bottom) + 96px); }\nbutton { font: inherit; color: inherit; cursor: pointer; }\nh1, h2, h3 { font-family: var(--display); font-weight: 400; margin: 0; line-height: 1.05; letter-spacing: .01em; }\n.muted { color: var(--grau); }\n.center { text-align: center; }\n.on-dark { color: #fff; }\n\n/* ---------- Bausteine ---------- */\n.card { background: var(--schaum); border: var(--rand); border-radius: var(--r); box-shadow: var(--schatten); padding: 18px; }\n.btn {\n  display: block; width: 100%; background: var(--bernstein); border: var(--rand); border-radius: 14px; box-shadow: var(--schatten);\n  padding: 14px 16px; font: 800 17px/1.1 var(--text); text-align: center; color: var(--tinte); transition: transform .08s, box-shadow .08s;\n}\n.btn:active:not(:disabled) { transform: translateY(4px); box-shadow: 0 1px 0 var(--tinte); }\n.btn:disabled { background: #d9d4c3; color: #7b7a72; box-shadow: 0 2px 0 var(--tinte); cursor: default; }\n.btn.blue { background: var(--himmel); color: #fff; }\n.btn.light { background: #fff; }\n.btn.red { background: var(--rot); color: #fff; }\n.btn.small { padding: 10px 12px; font-size: 15px; display: inline-block; width: auto; }\n.btn + .btn { margin-top: 12px; }\n.row { display: flex; gap: 12px; }\n.row > * { flex: 1; }\n.gap { margin-top: 14px; }\ninput[type=text] {\n  width: 100%; font: 700 20px var(--text); padding: 14px 16px; border: var(--rand); border-radius: 14px; background: #fff; color: var(--tinte); outline: none; -webkit-user-select: text; user-select: text;\n}\ninput[type=text]:focus-visible, .btn:focus-visible, button:focus-visible { outline: 4px solid #fff; outline-offset: 2px; box-shadow: 0 0 0 7px var(--himmel); }\n\n/* ---------- Anmeldung ---------- */\n.hero { padding: 26px 4px 8px; color: #fff; }\n.hero .krug { font-size: 76px; line-height: 1; display: inline-block; transform: rotate(-8deg); filter: drop-shadow(0 5px 0 rgba(0,0,0,.3)); }\n.hero h1 { font-size: 44px; margin-top: 10px; text-shadow: 0 4px 0 var(--tinte); }\n.hero p { font-size: 18px; font-weight: 700; margin: 10px 0 0; max-width: 24ch; opacity: .95; }\n.join { margin-top: 22px; }\n.join label { font-weight: 800; display: block; margin-bottom: 8px; }\n.rules { margin: 18px 4px 0; color: #dbe6ff; font-weight: 700; font-size: 15px; }\n.rules b { color: var(--bernstein); }\n\n/* ---------- Kopf (Punkte, Platz) ---------- */\n.top {\n  display: flex; align-items: center; gap: 12px; background: var(--schaum); border: var(--rand); border-radius: var(--r); box-shadow: var(--schatten); padding: 10px 14px 10px 10px;\n}\n.top .ava { width: 52px; height: 52px; border-radius: 50%; background: var(--bernstein); border: var(--rand); display: grid; place-items: center; font-size: 28px; flex: none; }\n.top .who { flex: 1; min-width: 0; }\n.top .who b { display: block; font-size: 17px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.top .who span { font-size: 13px; color: var(--grau); font-weight: 700; }\n.top .pts { text-align: right; }\n.top .pts b { font: 400 26px/1 var(--display); display: block; }\n.top .pts span { font-size: 13px; font-weight: 800; color: var(--himmel); }\n\n/* ---------- Spiele-Kacheln ---------- */\n.sec-title { color: #fff; font: 400 22px/1 var(--display); margin: 22px 2px 12px; }\n.sec-sub { color: #cfdcff; font-weight: 700; margin: -6px 2px 12px; font-size: 15px; }\n.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n.tile {\n  position: relative; text-align: left; background: var(--c, var(--bernstein)); border: var(--rand); border-radius: var(--r); box-shadow: var(--schatten);\n  padding: 12px 12px 12px; min-height: 142px; display: flex; flex-direction: column; justify-content: space-between; transition: transform .08s, box-shadow .08s;\n}\n.tile:active { transform: translateY(4px); box-shadow: 0 1px 0 var(--tinte); }\n.tile .em { font-size: 44px; line-height: 1; }\n.tile h3 { font-size: 17px; margin-top: 8px; }\n.tile .dur { font-size: 12.5px; font-weight: 800; opacity: .85; margin-top: 3px; }\n.tile .marks { display: flex; gap: 6px; margin-top: 10px; }\n.mark { font-size: 12px; font-weight: 800; padding: 3px 8px; border: 2px solid var(--tinte); border-radius: 99px; background: rgba(255,255,255,.55); }\n.mark.done { background: var(--tinte); color: #fff; }\n.tile.all { filter: saturate(.55) brightness(.97); }\n.tile.all::after { content: '⭐'; position: absolute; right: 10px; top: 8px; font-size: 22px; }\n\n/* ---------- Bottom Sheet ---------- */\n.scrim { position: fixed; inset: 0; z-index: 50; background: rgba(8,16,44,.72); display: flex; align-items: flex-end; justify-content: center; animation: fade .18s ease-out; }\n.scrim.mid { align-items: center; padding: 18px; }\n.sheet { width: 100%; max-width: 520px; background: var(--schaum); border: var(--rand); border-bottom: 0; border-radius: 26px 26px 0 0; padding: 22px 18px calc(env(safe-area-inset-bottom) + 20px); animation: up .22s cubic-bezier(.2,.9,.3,1); }\n.sheet .em { font-size: 54px; line-height: 1; }\n.sheet h2 { font-size: 28px; margin: 8px 0 6px; }\n.sheet p { margin: 0 0 14px; font-weight: 600; }\n.sheet .opt small { display: block; font-weight: 700; font-size: 13px; opacity: .8; margin-top: 4px; }\n.modal { width: 100%; max-width: 420px; background: var(--schaum); border: var(--rand); border-radius: 24px; box-shadow: 0 8px 0 var(--tinte); padding: 22px; text-align: center; animation: pop .26s cubic-bezier(.2,1.3,.4,1); }\n.modal .em { font-size: 64px; line-height: 1; }\n.modal h2 { font-size: 26px; margin: 10px 0 6px; }\n@keyframes fade { from { opacity: 0 } }\n@keyframes up { from { transform: translateY(40px); opacity: 0 } }\n@keyframes pop { from { transform: scale(.82); opacity: 0 } }\n\n/* ---------- Navigation unten ---------- */\n.nav { position: fixed; left: 0; right: 0; bottom: 0; z-index: 20; display: flex; justify-content: center; padding: 0 14px calc(env(safe-area-inset-bottom) + 12px); pointer-events: none; }\n.nav div { pointer-events: auto; width: 100%; max-width: 360px; display: flex; background: var(--schaum); border: var(--rand); border-radius: 99px; box-shadow: var(--schatten); padding: 5px; gap: 4px; }\n.nav button { flex: 1; border: 0; background: transparent; border-radius: 99px; padding: 11px 6px; font: 800 15px var(--text); color: var(--grau); }\n.nav button[aria-current=page] { background: var(--tinte); color: #fff; }\n\n/* ---------- Rangliste ---------- */\n.rank { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }\n.rank li { display: flex; align-items: center; gap: 12px; background: var(--schaum); border: var(--rand); border-radius: 16px; padding: 9px 14px 9px 10px; box-shadow: 0 3px 0 var(--tinte); }\n.rank li.me { background: var(--bernstein); }\n.rank .n { font: 400 20px var(--display); width: 30px; text-align: center; }\n.rank .a { font-size: 28px; }\n.rank .nm { flex: 1; min-width: 0; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.rank .nm small { display: block; font-weight: 700; color: var(--grau); font-size: 12.5px; }\n.rank li.me .nm small { color: var(--tinte); opacity: .7; }\n.rank .p { font: 400 19px var(--display); }\n.dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; background: #aeb4c9; margin-right: 6px; }\n.dot.on { background: var(--gruen); }\n.rank li.top1 { background: #ffe38a; padding: 14px; }\n.rank li.top1 .p { font-size: 24px; }\n.host { margin-top: 26px; padding-top: 18px; border-top: 3px dashed rgba(255,255,255,.35); color: #fff; }\n.host p { margin: 0 0 12px; font-weight: 700; }\n\n/* ---------- Gegner würfeln ---------- */\n.draw { text-align: center; color: #fff; padding-top: 16px; }\n.draw h2 { font-size: 30px; text-shadow: 0 3px 0 var(--tinte); }\n.draw .sub { font-weight: 700; margin: 8px 0 0; color: #dbe6ff; }\n.reel { width: 190px; height: 190px; margin: 26px auto 14px; border-radius: 50%; background: var(--schaum); border: var(--rand); box-shadow: 0 8px 0 var(--tinte); display: grid; place-items: center; font-size: 100px; line-height: 1; color: var(--tinte); position: relative; }\n.reel.spin { animation: wob .18s infinite alternate; }\n.reel.land { animation: land .5s cubic-bezier(.2,1.5,.4,1); background: var(--bernstein); }\n@keyframes wob { from { transform: rotate(-4deg) } to { transform: rotate(4deg) } }\n@keyframes land { from { transform: scale(.7) } }\n.cand { min-height: 94px; }\n.cand .nm { font: 400 32px/1.05 var(--display); text-shadow: 0 3px 0 var(--tinte); animation: pop .35s cubic-bezier(.2,1.4,.4,1); }\n.cand .meta { font-weight: 800; margin-top: 6px; color: #dbe6ff; }\n.cand .ghost { font-weight: 800; color: #9db4ee; padding-top: 30px; }\n.draw .btns { margin-top: 18px; display: grid; gap: 12px; }\n\n/* ---------- Warten ---------- */\n.waitbox { text-align: center; color: #fff; padding-top: 40px; }\n.waitbox .em { font-size: 86px; display: inline-block; animation: wob .5s infinite alternate; }\n.waitbox h2 { font-size: 30px; margin: 14px 0 8px; text-shadow: 0 3px 0 var(--tinte); }\n.waitbox p { font-weight: 700; color: #dbe6ff; margin: 0 auto 22px; max-width: 28ch; }\n\n/* ---------- Intro + Spiel ---------- */\n.intro { text-align: center; padding: 24px 6px 0; color: #fff; }\n.intro .big { font-size: 96px; line-height: 1; filter: drop-shadow(0 6px 0 rgba(0,0,0,.28)); }\n.intro h2 { font-size: 36px; margin: 14px 0 10px; text-shadow: 0 4px 0 var(--tinte); }\n.intro .rule { font-size: 19px; font-weight: 700; margin: 0 auto 20px; max-width: 26ch; }\n.vs { display: flex; align-items: center; justify-content: center; gap: 10px; margin: 0 0 18px; font-weight: 800; }\n.vs span { background: var(--schaum); color: var(--tinte); border: var(--rand); border-radius: 99px; padding: 6px 12px; }\n.vs i { font-style: normal; font: 400 20px var(--display); color: var(--bernstein); text-shadow: 0 2px 0 var(--tinte); }\n.play { position: fixed; inset: 0; z-index: 30; display: flex; flex-direction: column; background: var(--himmel); padding-top: env(safe-area-inset-top); }\n.play::before { content: ''; position: absolute; inset: -60%; transform: rotate(45deg); background: conic-gradient(rgba(255,255,255,.08) 25%, transparent 0 50%, rgba(255,255,255,.08) 0 75%, transparent 0) 0 0 / 84px 84px; z-index: 0; }\n.hud { position: relative; z-index: 1; display: flex; align-items: center; gap: 10px; padding: 10px 12px; color: #fff; font-weight: 800; }\n.hud .x { width: 40px; height: 40px; border-radius: 50%; border: var(--rand); background: var(--schaum); color: var(--tinte); font-size: 20px; line-height: 1; padding: 0; }\n.hud .gname { flex: 1; font-size: 30px; line-height: 1; white-space: nowrap; overflow: hidden; }\n.hud .gname span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.hud .hv { background: var(--tinte); border-radius: 99px; padding: 7px 12px; font-size: 15px; font-variant-numeric: tabular-nums; min-width: 64px; text-align: center; }\n.bar { position: relative; z-index: 1; height: 10px; margin: 0 12px; background: rgba(0,0,0,.28); border-radius: 99px; overflow: hidden; border: 2px solid var(--tinte); }\n.bar i { display: block; height: 100%; width: 100%; background: var(--bernstein); transform-origin: left; transition: transform .2s linear; }\n.stage { position: relative; z-index: 1; flex: 1; display: flex; flex-direction: column; padding: 14px 12px calc(env(safe-area-inset-bottom) + 16px); min-height: 0; }\n\n/* ---------- Ergebnis ---------- */\n.result { text-align: center; color: #fff; padding-top: 18px; }\n.result .em { font-size: 78px; line-height: 1; }\n.result h2 { font-size: 32px; margin: 10px 0 4px; text-shadow: 0 3px 0 var(--tinte); }\n.result .score { font: 400 84px/1 var(--display); color: var(--bernstein); text-shadow: 0 5px 0 var(--tinte); margin: 14px 0 2px; font-variant-numeric: tabular-nums; }\n.result .score small { font-size: 22px; }\n.result .detail { font-weight: 700; color: #dbe6ff; }\n.versus { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 20px 0; }\n.versus .side { background: var(--schaum); color: var(--tinte); border: var(--rand); border-radius: 18px; padding: 14px 8px; box-shadow: var(--schatten); }\n.versus .side.win { background: var(--bernstein); transform: translateY(-6px) rotate(-1.5deg); }\n.versus .a { font-size: 44px; line-height: 1; }\n.versus b { display: block; font-size: 15px; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.versus .v { font: 400 34px var(--display); margin-top: 4px; font-variant-numeric: tabular-nums; }\n.versus .bn { font-size: 13px; font-weight: 800; }\n.result .btns { margin-top: 22px; }\n\n/* ---------- Ende ---------- */\n.podium { display: grid; grid-template-columns: 1fr 1.15fr 1fr; align-items: end; gap: 10px; margin: 18px 0 22px; }\n.podium .pl { text-align: center; color: #fff; font-weight: 800; font-size: 13.5px; }\n.podium .pl .a { font-size: 40px; line-height: 1; }\n.podium .pl .blk { margin-top: 6px; background: var(--bernstein); border: var(--rand); border-radius: 12px 12px 0 0; color: var(--tinte); font: 400 28px var(--display); padding-top: 8px; }\n.podium .p1 .blk { height: 112px; } .podium .p2 .blk { height: 80px; background: #dfe6f7; } .podium .p3 .blk { height: 58px; background: #e9a46a; }\n\n/* ---------- Status, Toast ---------- */\n#toast { position: fixed; left: 50%; top: calc(env(safe-area-inset-top) + 14px); transform: translate(-50%, -140%); z-index: 100; background: var(--tinte); color: #fff; font-weight: 800; padding: 12px 18px; border-radius: 99px; border: 3px solid #fff; max-width: 90vw; text-align: center; transition: transform .25s cubic-bezier(.2,1.2,.4,1); pointer-events: none; }\n#toast.show { transform: translate(-50%, 0); }\n.net { position: fixed; right: 10px; top: calc(env(safe-area-inset-top) + 6px); z-index: 15; font: 800 11px var(--text); padding: 3px 9px; border-radius: 99px; background: var(--tinte); color: #fff; opacity: .85; }\n.net::before { content: '● '; color: var(--gruen); }\n.net.off::before { color: var(--rot); }\n.net.on { display: none; }\nbody.playing .net { display: none; }\n\n/* ================= Spiel-Oberflächen ================= */\n.g-center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 16px; text-align: center; color: #fff; }\n.g-q { font: 400 24px/1.15 var(--display); color: #fff; text-shadow: 0 3px 0 var(--tinte); text-align: center; margin: 6px 4px 18px; min-height: 84px; display: flex; align-items: center; justify-content: center; }\n.answers { display: grid; gap: 12px; }\n.ans { background: var(--schaum); border: var(--rand); border-radius: 14px; box-shadow: var(--schatten); padding: 15px 14px; font: 800 18px var(--text); text-align: left; transition: transform .08s; }\n.ans:active { transform: translateY(3px); }\n.ans.right { background: var(--gruen); color: #fff; }\n.ans.wrong { background: var(--rot); color: #fff; }\n.ans:disabled { opacity: 1; }\n\n.react { flex: 1; border: var(--rand); border-radius: 26px; box-shadow: 0 8px 0 var(--tinte); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; color: #fff; background: var(--nacht); padding: 20px; width: 100%; }\n.react.go { background: var(--bernstein); color: var(--tinte); }\n.react.bad { background: var(--rot); }\n.react .rb { font: 400 46px/1 var(--display); text-shadow: 0 3px 0 rgba(0,0,0,.25); }\n.react .rs { font-weight: 800; font-size: 17px; opacity: .9; }\n.react .re { font-size: 84px; line-height: 1; }\n\n.masz { flex: 1; width: 100%; border: var(--rand); border-radius: 26px; box-shadow: 0 8px 0 var(--tinte); background: var(--bernstein); position: relative; overflow: hidden; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }\n.masz .fill { position: absolute; left: 0; right: 0; bottom: 0; height: 0; background: #ffe38a; transition: height .08s linear; }\n.masz > * { position: relative; }\n.masz .em { font-size: 96px; line-height: 1; transition: transform .06s; }\n.masz.hit .em { transform: translateY(-14px) scale(1.12); }\n.masz .cnt { font: 400 70px/1 var(--display); text-shadow: 0 4px 0 rgba(0,0,0,.2); font-variant-numeric: tabular-nums; }\n.masz .lbl { font-weight: 800; }\n\n.field { position: relative; flex: 1; border: var(--rand); border-radius: 22px; background: rgba(15,42,102,.55); overflow: hidden; touch-action: none; }\n.tg { position: absolute; width: 68px; height: 68px; margin: -34px 0 0 -34px; border: 0; background: none; font-size: 54px; line-height: 1; padding: 0; animation: tgpop .16s cubic-bezier(.2,1.5,.4,1); }\n.tg.gone { transition: transform .18s, opacity .18s; transform: scale(1.6); opacity: 0; pointer-events: none; }\n.tg.bad.gone { transform: scale(.4) rotate(40deg); }\n@keyframes tgpop { from { transform: scale(.2) } }\n.field .flash { position: absolute; inset: 0; background: var(--rot); opacity: 0; pointer-events: none; }\n.field .flash.on { animation: fl .3s; }\n@keyframes fl { 0% { opacity: .5 } 100% { opacity: 0 } }\n\n.cards { flex: 1; display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: 1fr; gap: 10px; align-content: center; max-height: 480px; margin: auto 0; }\n.cd { perspective: 600px; border: 0; background: none; padding: 0; min-height: 80px; }\n.cd .in { position: relative; width: 100%; height: 100%; transition: transform .28s; transform-style: preserve-3d; }\n.cd.open .in, .cd.done .in { transform: rotateY(180deg); }\n.cd .f, .cd .b { position: absolute; inset: 0; border: var(--rand); border-radius: 14px; backface-visibility: hidden; -webkit-backface-visibility: hidden; display: grid; place-items: center; box-shadow: 0 4px 0 var(--tinte); }\n.cd .f { background: var(--schaum); transform: rotateY(180deg); font-size: 40px; }\n.cd .b { background: var(--nacht); color: var(--bernstein); font: 400 30px var(--display); background-image: conic-gradient(rgba(255,255,255,.18) 25%, transparent 0 50%, rgba(255,255,255,.18) 0 75%, transparent 0); background-size: 22px 22px; }\n.cd.done .f { background: #c9f0d6; }\n\n.glass-wrap { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; }\n.glass { position: relative; width: 150px; height: 250px; border: var(--rand); border-radius: 10px 10px 34px 34px; background: rgba(255,255,255,.85); overflow: hidden; box-shadow: var(--schatten); }\n.glass .liq { position: absolute; left: 0; right: 0; bottom: 0; height: 0; background: var(--bernstein); }\n.glass .liq::before { content: ''; position: absolute; left: 0; right: 0; top: -9px; height: 12px; background: #fff; border-radius: 99px 99px 0 0; opacity: .0; }\n.glass.has-foam .liq::before { opacity: 1; }\n.glass .target { position: absolute; left: -4px; right: -4px; height: 0; border-top: 4px dashed var(--rot); }\n.glass .target::after { content: '◀ Strich'; position: absolute; right: 8px; top: -26px; font: 800 12px var(--text); color: var(--rot); background: rgba(255,255,255,.9); padding: 1px 5px; border-radius: 6px; display: none; }\n.hold { width: 100%; max-width: 360px; }\n.sliderbox { background: var(--schaum); border: var(--rand); border-radius: 18px; box-shadow: var(--schatten); padding: 20px 16px; text-align: center; }\n.sliderbox .val { font: 400 42px/1 var(--display); margin: 4px 0 4px; font-variant-numeric: tabular-nums; }\n.sliderbox .unit { font-weight: 800; color: var(--grau); margin-bottom: 14px; }\ninput[type=range] { width: 100%; height: 44px; accent-color: var(--himmel); }\n.truth { font-weight: 800; min-height: 28px; margin-top: 8px; }\n\n.pads { flex: 1; display: grid; grid-template-columns: 1fr 1fr; grid-auto-rows: 1fr; gap: 12px; max-height: 440px; margin: auto 0; }\n.pad { border: var(--rand); border-radius: 22px; box-shadow: var(--schatten); background: var(--pc); font-size: 52px; opacity: .85; transition: transform .06s, opacity .06s, filter .06s; }\n.pad.lit { opacity: 1; transform: scale(.94); filter: brightness(1.25) saturate(1.2); box-shadow: 0 0 0 5px #fff, var(--schatten); }\n.say { text-align: center; color: #fff; font: 400 22px var(--display); min-height: 32px; text-shadow: 0 2px 0 var(--tinte); margin-bottom: 8px; }\n\n.sumq { background: var(--schaum); border: var(--rand); border-radius: 18px; box-shadow: var(--schatten); padding: 18px 16px; margin-bottom: 18px; text-align: center; }\n.sumq .l { font: 800 20px/1.5 var(--text); }\n.sumq .t { font-weight: 800; color: var(--grau); margin-top: 8px; }\n.score-pill { color: #fff; text-align: center; font-weight: 800; margin-top: 12px; }\n\n.lukas { flex: 1; display: flex; align-items: stretch; justify-content: center; gap: 22px; min-height: 0; }\n.tower { position: relative; width: 96px; border: var(--rand); border-radius: 48px 48px 14px 14px; background: linear-gradient(to top, #bfe6c8 0 55%, #ffe38a 55% 80%, #ffb21a 80% 94%, #e8433f 94%); box-shadow: var(--schatten); overflow: hidden; }\n.tower .mk { position: absolute; left: 0; right: 0; bottom: 0; height: 6px; background: var(--tinte); box-shadow: 0 0 0 3px #fff; }\n.tower .glow { position: absolute; left: 0; right: 0; bottom: 0; background: rgba(18,27,58,.28); }\n.lukas .side { display: flex; flex-direction: column; justify-content: space-between; align-items: center; color: #fff; text-align: center; padding: 4px 0; }\n.lukas .bell { font-size: 56px; transition: transform .1s; }\n.lukas .bell.ring { animation: ring .6s; }\n@keyframes ring { 0%,100% { transform: rotate(0) } 20% { transform: rotate(-28deg) } 40% { transform: rotate(24deg) } 60% { transform: rotate(-16deg) } 80% { transform: rotate(10deg) } }\n.lukas .info { font: 400 20px var(--display); text-shadow: 0 2px 0 var(--tinte); }\n.hammer { width: 150px; height: 150px; border-radius: 50%; border: var(--rand); box-shadow: 0 8px 0 var(--tinte); background: var(--bernstein); font-size: 70px; padding: 0; }\n.hammer:active { transform: translateY(6px); box-shadow: 0 2px 0 var(--tinte); }\n\n@media (prefers-reduced-motion: reduce) { * { animation-duration: .01ms !important; transition-duration: .01ms !important; } }\n@media (max-height: 640px) { .reel { width: 150px; height: 150px; font-size: 76px; margin-top: 10px; } .glass { height: 190px; } .hero .krug { font-size: 56px; } }\n", "games.js": "'use strict';\n// 10 kurze Spiele. Jedes Spiel läuft solo und im Duell identisch; im Duell bekommen beide denselben Seed (gleiche Aufgaben).\n// run(c): c.el (Spielfläche), c.rng() (Seed-Zufall), c.hud(links, rechts, anteil 0..1), c.after(ms, fn), c.every(ms, fn),\n//         c.raf(fn), c.finish(punkte 0..1000, text), c.vib(ms), c.tone(freq, ms)\n(function () {\n  const mulberry32 = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };\n  const shuffle = (rng, arr) => { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };\n  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));\n  const eur = n => n.toFixed(2).replace('.', ',') + ' €';\n  const num = n => String(n).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ' ');\n  const esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n\n  const GAMES = [];\n  const add = g => GAMES.push(g);\n\n  // 1 ---------------------------------------------------------------- Prosit-Reflex\n  add({\n    id: 'prosit', name: 'Prosit-Reflex', em: '🍻', color: '#ffb21a', secs: 25,\n    rule: 'Der Krug wartet. Sobald er golden wird: sofort tippen. Zu früh tippen gibt 0 Punkte.',\n    run(c) {\n      const ROUNDS = 3, delays = Array.from({ length: ROUNDS }, () => 1300 + Math.floor(c.rng() * 2600));\n      let round = 0, sum = 0, times = [], state = 'pause', t0 = 0, goTimer = null;\n      c.el.innerHTML = '<button class=\"react\" id=\"rb\"><span class=\"re\"></span><span class=\"rb\"></span><span class=\"rs\"></span></button>';\n      const b = c.el.querySelector('#rb'), re = b.querySelector('.re'), rb = b.querySelector('.rb'), rs = b.querySelector('.rs');\n      const set = (cls, e, big, sub) => { b.className = 'react ' + cls; re.textContent = e; rb.textContent = big; rs.textContent = sub; };\n      function next() {\n        if (round >= ROUNDS) return end();\n        c.hud(`Runde ${round + 1}/${ROUNDS}`, '', round / ROUNDS);\n        state = 'wait'; set('', '🍺', 'Warten …', 'Tippe, sobald der Krug golden wird');\n        goTimer = c.after(delays[round], () => { state = 'go'; t0 = performance.now(); set('go', '🍻', 'PROSIT!', 'Jetzt tippen!'); c.vib(30); });\n      }\n      function score(ms, early) {\n        state = 'pause';\n        let pts = 0, line;\n        if (early) { line = 'Zu früh – 0 Punkte'; set('bad', '🙈', 'Zu früh!', '0 Punkte'); }\n        else { pts = clamp(Math.round(1000 * (1 - (ms - 200) / 650)), 0, 1000); times.push(ms); line = `${ms} ms`; set('go', '⚡', `${ms} ms`, `${pts} Punkte`); }\n        sum += pts; round++;\n        c.after(1000, next);\n      }\n      b.addEventListener('pointerdown', e => {\n        e.preventDefault();\n        if (state === 'wait') { goTimer && goTimer(); score(0, true); }\n        else if (state === 'go') score(Math.round(performance.now() - t0), false);\n      });\n      function end() {\n        const avg = times.length ? Math.round(times.reduce((a, x) => a + x, 0) / times.length) : 0;\n        c.finish(Math.round(sum / ROUNDS), times.length ? `Ø ${avg} ms Reaktionszeit` : 'Dreimal zu früh');\n      }\n      next();\n    },\n  });\n\n  // 2 ---------------------------------------------------------------- Maßkrug-Stemmen\n  add({\n    id: 'stemmen', name: 'Maßkrug-Stemmen', em: '💪', color: '#ff6f61', secs: 12,\n    rule: 'Tippe so schnell du kannst. Die Zeit läuft ab dem ersten Tipp: 8 Sekunden.',\n    run(c) {\n      const TOTAL = 8000, GOAL = 70;\n      let taps = 0, started = 0, done = false;\n      c.el.innerHTML = '<button class=\"masz\" id=\"mz\"><div class=\"fill\"></div><span class=\"em\">🍺</span><span class=\"cnt\">0</span><span class=\"lbl\">Tippe los!</span></button>';\n      const mz = c.el.querySelector('#mz'), fill = mz.querySelector('.fill'), cnt = mz.querySelector('.cnt'), lbl = mz.querySelector('.lbl');\n      c.hud('Bereit', '8,0 s', 1);\n      mz.addEventListener('pointerdown', e => {\n        e.preventDefault(); if (done) return;\n        if (!started) { started = performance.now(); lbl.textContent = 'Weiter, weiter!'; c.raf(tick); }\n        taps++; cnt.textContent = taps; fill.style.height = clamp(taps / GOAL * 100, 0, 100) + '%';\n        mz.classList.add('hit'); c.after(60, () => mz.classList.remove('hit')); c.vib(8);\n      });\n      function tick() {\n        const left = Math.max(0, TOTAL - (performance.now() - started));\n        c.hud('Stemmen', (left / 1000).toFixed(1).replace('.', ',') + ' s', left / TOTAL);\n        if (left <= 0) { done = true; return c.finish(clamp(Math.round(taps / GOAL * 1000), 0, 1000), `${taps} Tipps in 8 Sekunden`); }\n        c.raf(tick);\n      }\n    },\n  });\n\n  // 3 ---------------------------------------------------------------- Brezn-Jagd\n  add({\n    id: 'brezn', name: 'Brezn-Jagd', em: '🥨', color: '#e07a1f', secs: 25,\n    rule: 'Tippe die Brezn 🥨 an, bevor sie verschwinden. Finger weg vom verschütteten Bier 🍺: das kostet Punkte.',\n    run(c) {\n      const TOTAL = 20000;\n      const sched = []; let t = 500;\n      while (t < TOTAL - 1200) { sched.push({ t, x: 10 + c.rng() * 80, y: 8 + c.rng() * 84, bad: c.rng() < 0.22 }); t += 430 + c.rng() * 280; }\n      const goodTotal = sched.filter(s => !s.bad).length;\n      let good = 0, bad = 0, idx = 0, started = performance.now();\n      c.el.innerHTML = '<div class=\"field\" id=\"fd\"><div class=\"flash\"></div></div>';\n      const fd = c.el.querySelector('#fd'), flash = fd.querySelector('.flash');\n      function spawn(s) {\n        const el = document.createElement('button'); el.className = 'tg' + (s.bad ? ' bad' : ''); el.textContent = s.bad ? '🍺' : '🥨';\n        el.style.left = s.x + '%'; el.style.top = s.y + '%'; fd.appendChild(el);\n        let alive = true;\n        const kill = () => { alive = false; el.classList.add('gone'); c.after(220, () => el.remove()); };\n        el.addEventListener('pointerdown', e => {\n          e.preventDefault(); e.stopPropagation(); if (!alive) return; kill();\n          if (s.bad) { bad++; flash.classList.remove('on'); void flash.offsetWidth; flash.classList.add('on'); c.vib(60); } else { good++; c.vib(8); }\n        });\n        c.after(1150, () => { if (alive) kill(); });\n      }\n      function tick() {\n        const el = performance.now() - started;\n        while (idx < sched.length && sched[idx].t <= el) spawn(sched[idx++]);\n        c.hud(`${good} 🥨`, Math.max(0, Math.ceil((TOTAL - el) / 1000)) + ' s', 1 - el / TOTAL);\n        if (el >= TOTAL) return c.after(1000, () => c.finish(clamp(Math.round(1000 * Math.max(0, good - 2 * bad) / (goodTotal * 0.85)), 0, 1000), `${good} Brezn gefangen, ${bad}× Bier erwischt`));\n        c.raf(tick);\n      }\n      c.raf(tick);\n    },\n  });\n\n  // 4 ---------------------------------------------------------------- Wiesn-Quiz\n  const QUIZ = [\n    ['Wie viel Bier passt in eine Wiesn-Maß?', '1 Liter', '0,5 Liter', '0,75 Liter', '1,5 Liter'],\n    ['Wo findet das Oktoberfest statt?', 'Theresienwiese', 'Marienplatz', 'Olympiapark', 'Englischer Garten'],\n    ['Wie heißt die traditionelle Tracht für Frauen?', 'Dirndl', 'Kimono', 'Poncho', 'Sari'],\n    ['Was ruft man traditionell nach dem Anzapfen des ersten Fasses?', 'O’zapft is!', 'Servus!', 'Ois Guade!', 'Hurra!'],\n    ['Was bedeutet »Prosit«?', 'Zum Wohl', 'Guten Appetit', 'Auf Wiedersehen', 'Danke'],\n    ['Welche Zutat ist laut Reinheitsgebot NICHT im Bier erlaubt?', 'Zucker', 'Hopfen', 'Malz', 'Wasser'],\n    ['Welche Farben hat die bayerische Raute?', 'Weiß und Blau', 'Rot und Gelb', 'Grün und Weiß', 'Schwarz und Gold'],\n    ['Was isst man traditionell zur Weißwurst?', 'Süßen Senf', 'Ketchup', 'Mayonnaise', 'Wasabi'],\n    ['Wie heißt der höchste Berg Deutschlands?', 'Zugspitze', 'Watzmann', 'Feldberg', 'Brocken'],\n    ['Wie heißt der Fluss, der durch München fließt?', 'Isar', 'Donau', 'Main', 'Inn'],\n    ['Was ist ein »Hendl«?', 'Ein Brathähnchen', 'Ein Schweinebraten', 'Ein Knödel', 'Ein Kartoffelsalat'],\n    ['Was ist »Obazda«?', 'Eine Käsecreme', 'Eine Wurst', 'Ein Kuchen', 'Eine Suppe'],\n    ['Welches Instrument gehört klassisch zur Blasmusik?', 'Tuba', 'Harfe', 'Geige', 'Sitar'],\n    ['Wie heißt die Schweizer Hauptstadt?', 'Bern', 'Zürich', 'Genf', 'Basel'],\n    ['Was ist ein »Radler«?', 'Bier mit Limonade', 'Ein Fahrradfahrer mit Bier', 'Bier mit Cola und Rum', 'Alkoholfreies Weißbier'],\n    ['Wie viele Tage dauert das Oktoberfest ungefähr?', '16 bis 18', '7', '30', '3'],\n    ['Was wurde 1810 mit dem ersten Oktoberfest gefeiert?', 'Eine königliche Hochzeit', 'Ein Sieg im Krieg', 'Eine Bierernte', 'Ein Stadtjubiläum'],\n    ['Was bedeutet »Servus« in Bayern?', 'Hallo und Tschüss', 'Danke', 'Entschuldigung', 'Prost'],\n    ['Wie nennt man ein Dutzend?', '12 Stück', '10 Stück', '20 Stück', '24 Stück'],\n    ['Welche Tracht trägt man traditionell zur Lederhose am Fuß?', 'Haferlschuhe', 'Flip-Flops', 'Ballettschuhe', 'Stiefel mit Stahlkappe'],\n  ];\n  add({\n    id: 'quiz', name: 'Wiesn-Quiz', em: '🧠', color: '#8e6bff', secs: 45,\n    rule: 'Fünf Fragen, je 12 Sekunden. Richtig und schnell bringt am meisten Punkte.',\n    run(c) {\n      const N = 5, T = 12000, qs = shuffle(c.rng, QUIZ).slice(0, N).map(q => ({ q: q[0], ans: shuffle(c.rng, q.slice(1).map((t, i) => ({ t, ok: i === 0 }))) }));\n      let i = 0, pts = 0, right = 0, locked = false, t0 = 0;\n      c.el.innerHTML = '<div class=\"g-q\" id=\"gq\"></div><div class=\"answers\" id=\"ga\"></div>';\n      const gq = c.el.querySelector('#gq'), ga = c.el.querySelector('#ga');\n      function show() {\n        if (i >= N) return c.finish(Math.min(1000, pts), `${right} von ${N} richtig`);\n        const q = qs[i]; locked = false; t0 = performance.now();\n        gq.textContent = q.q; ga.innerHTML = '';\n        q.ans.forEach(a => { const b = document.createElement('button'); b.className = 'ans'; b.textContent = a.t; b.addEventListener('pointerdown', e => { e.preventDefault(); pick(b, a); }); ga.appendChild(b); });\n        tick();\n      }\n      function reveal(chosen) {\n        locked = true;\n        [...ga.children].forEach((b, k) => { b.disabled = true; if (q().ans[k].ok) b.classList.add('right'); else if (b === chosen) b.classList.add('wrong'); });\n        c.after(1000, () => { i++; show(); });\n      }\n      const q = () => qs[i];\n      function pick(b, a) {\n        if (locked) return; const left = Math.max(0, T - (performance.now() - t0));\n        if (a.ok) { right++; pts += 120 + Math.round(80 * left / T); c.vib(15); } else c.vib(60);\n        reveal(b);\n      }\n      function tick() {\n        if (locked) return; const left = T - (performance.now() - t0);\n        c.hud(`Frage ${i + 1}/${N}`, Math.max(0, Math.ceil(left / 1000)) + ' s', Math.max(0, left / T));\n        if (left <= 0) return reveal(null);\n        c.after(100, tick);\n      }\n      show();\n    },\n  });\n\n  // 5 ---------------------------------------------------------------- Memory\n  add({\n    id: 'memory', name: 'Wiesn-Memory', em: '🃏', color: '#2ec4b6', secs: 45,\n    rule: 'Finde alle 6 Paare. Die 45 Sekunden laufen ab der ersten aufgedeckten Karte. Schnell fertig gibt Bonus.',\n    run(c) {\n      const TOTAL = 45000, faces = shuffle(c.rng, ['🥨', '🍺', '🍗', '🎺', '👒', '🎡', '🍻', '🧀', '🐷', '🎯']).slice(0, 6);\n      const deck = shuffle(c.rng, [...faces, ...faces]);\n      let open = [], pairs = 0, started = 0, lock = false, ended = false;\n      c.el.innerHTML = '<div class=\"cards\" id=\"cs\"></div>';\n      const cs = c.el.querySelector('#cs');\n      deck.forEach((f, k) => {\n        const b = document.createElement('button'); b.className = 'cd'; b.innerHTML = `<div class=\"in\"><div class=\"b\">?</div><div class=\"f\">${f}</div></div>`;\n        b.addEventListener('pointerdown', e => { e.preventDefault(); flip(b, k); }); cs.appendChild(b);\n      });\n      c.hud('0 von 6 Paaren', '45 s', 1);\n      function flip(b, k) {\n        if (lock || ended || b.classList.contains('open') || b.classList.contains('done')) return;\n        if (!started) { started = performance.now(); c.raf(tick); }\n        b.classList.add('open'); open.push({ b, k }); c.vib(8);\n        if (open.length === 2) {\n          lock = true; const [x, y] = open;\n          if (deck[x.k] === deck[y.k]) { c.after(300, () => { x.b.classList.replace('open', 'done'); y.b.classList.replace('open', 'done'); open = []; lock = false; pairs++; if (pairs === 6) end(); }); }\n          else c.after(750, () => { x.b.classList.remove('open'); y.b.classList.remove('open'); open = []; lock = false; });\n        }\n      }\n      function tick() {\n        if (ended) return; const left = Math.max(0, TOTAL - (performance.now() - started));\n        c.hud(`${pairs} von 6 Paaren`, Math.ceil(left / 1000) + ' s', left / TOTAL);\n        if (left <= 0) return end(); c.raf(tick);\n      }\n      function end() {\n        if (ended) return; ended = true; const left = Math.max(0, TOTAL - (performance.now() - started));\n        const pts = pairs * 100 + (pairs === 6 ? Math.min(400, Math.round(left / 1000 * 9)) : 0);\n        c.after(500, () => c.finish(clamp(pts, 0, 1000), pairs === 6 ? `Alle Paare in ${((TOTAL - left) / 1000).toFixed(1).replace('.', ',')} s` : `${pairs} von 6 Paaren`));\n      }\n    },\n  });\n\n  // 6 ---------------------------------------------------------------- Perfekt zapfen\n  add({\n    id: 'zapfen', name: 'Perfekt zapfen', em: '🍺', color: '#f5c542', secs: 30,\n    rule: 'Halte den Knopf gedrückt, das Glas füllt sich. Lass genau am roten Strich los. Dreimal.',\n    run(c) {\n      const R = 3, targets = Array.from({ length: R }, () => 0.5 + c.rng() * 0.4), SPEED = 0.5;\n      let round = 0, sum = 0, level = 0, holding = false, last = 0, locked = true, detail = [];\n      c.el.innerHTML = '<div class=\"glass-wrap\"><div class=\"glass\" id=\"gl\"><div class=\"liq\" id=\"lq\"></div><div class=\"target\" id=\"tg\"></div></div><div class=\"say\" id=\"sy\"></div><button class=\"btn hold\" id=\"hd\">Gedrückt halten zum Zapfen</button></div>';\n      const gl = c.el.querySelector('#gl'), lq = c.el.querySelector('#lq'), tg = c.el.querySelector('#tg'), sy = c.el.querySelector('#sy'), hd = c.el.querySelector('#hd');\n      function setup() {\n        if (round >= R) return c.finish(clamp(sum, 0, 1000), detail.join(' · '));\n        level = 0; lq.style.height = '0'; gl.classList.remove('has-foam'); tg.style.bottom = (targets[round] * 100) + '%'; tg.style.top = 'auto';\n        sy.textContent = ''; locked = false; c.hud(`Glas ${round + 1}/${R}`, '', round / R);\n      }\n      function loop(ts) {\n        if (!holding) return; const dt = last ? (ts - last) / 1000 : 0; last = ts; level += dt * SPEED; lq.style.height = Math.min(level, 1) * 100 + '%';\n        if (level >= 1) return release(true); c.raf(loop);\n      }\n      function release(over) {\n        if (!holding) return; holding = false; locked = true; gl.classList.add('has-foam');\n        const diff = Math.abs(level - targets[round]); const pts = over ? 0 : Math.round(333.4 * Math.max(0, 1 - diff / 0.25));\n        sum += pts; detail.push(over ? 'übergelaufen' : `${Math.round((1 - diff) * 100)} %`);\n        sy.textContent = over ? 'Übergelaufen! 0 Punkte' : (diff < 0.03 ? `Perfekt! ${pts} Punkte` : `${pts} Punkte`); c.vib(over ? 80 : 20);\n        round++; c.after(1200, setup);\n      }\n      hd.addEventListener('pointerdown', e => { e.preventDefault(); if (locked || holding) return; holding = true; last = 0; hd.textContent = 'Lass am Strich los!'; c.raf(loop); });\n      for (const ev of ['pointerup', 'pointercancel']) window.addEventListener(ev, onUp); c.onClean(() => { for (const ev of ['pointerup', 'pointercancel']) window.removeEventListener(ev, onUp); });\n      function onUp() { if (holding) { hd.textContent = 'Gedrückt halten zum Zapfen'; release(false); } }\n      setup();\n    },\n  });\n\n  // 7 ---------------------------------------------------------------- Schätzfrage\n  const EST = [\n    ['Wie hoch ist die Zugspitze?', 'Meter', 2962, 1000, 5000, 50, 1500, v => num(v)],\n    ['In welchem Jahr gab es das erste Oktoberfest?', 'Jahr', 1810, 1700, 1950, 1, 60, v => String(v)],\n    ['Wie viele Einwohner hat München ungefähr?', 'Millionen', 1.5, 0.5, 4, 0.1, 1, v => String(v).replace('.', ',')],\n    ['Wie viele Knochen hat ein Erwachsener?', 'Knochen', 206, 100, 400, 1, 100, v => String(v)],\n    ['Wie hoch ist der Eiffelturm (mit Antenne)?', 'Meter', 330, 100, 600, 5, 150, v => String(v)],\n    ['Wie hoch ist der Mount Everest?', 'Meter', 8849, 5000, 12000, 50, 3000, v => num(v)],\n    ['Seit welchem Jahr gilt das bayerische Reinheitsgebot?', 'Jahr', 1516, 1300, 1800, 1, 150, v => String(v)],\n    ['Wie viele Tasten hat ein Klavier?', 'Tasten', 88, 40, 150, 1, 40, v => String(v)],\n    ['Wie viele Kantone hat die Schweiz?', 'Kantone', 26, 10, 50, 1, 15, v => String(v)],\n  ];\n  add({\n    id: 'schaetzen', name: 'Schätzfrage', em: '📏', color: '#5b9bff', secs: 50,\n    rule: 'Vier Schätzfragen mit Schieberegler. Je näher dran, desto mehr Punkte. 15 Sekunden pro Frage.',\n    run(c) {\n      const N = 4, T = 15000, qs = shuffle(c.rng, EST).slice(0, N);\n      let i = 0, sum = 0, locked = false, t0 = 0, val = 0;\n      c.el.innerHTML = '<div class=\"g-q\" id=\"gq\"></div><div class=\"sliderbox\"><div class=\"val\" id=\"vl\"></div><div class=\"unit\" id=\"un\"></div><input type=\"range\" id=\"rg\" aria-label=\"Schätzwert\"><div class=\"truth\" id=\"tr\"></div></div><button class=\"btn gap\" id=\"ok\">Festlegen</button>';\n      const gq = c.el.querySelector('#gq'), vl = c.el.querySelector('#vl'), un = c.el.querySelector('#un'), rg = c.el.querySelector('#rg'), tr = c.el.querySelector('#tr'), ok = c.el.querySelector('#ok');\n      function show() {\n        if (i >= N) return c.finish(clamp(Math.round(sum), 0, 1000), `${N} Schätzungen`);\n        const q = qs[i]; locked = false; t0 = performance.now(); tr.textContent = ''; ok.disabled = false;\n        gq.textContent = q[0]; un.textContent = q[1]; rg.min = q[3]; rg.max = q[4]; rg.step = q[5]; val = +((q[3] + q[4]) / 2).toFixed(2); rg.value = val; vl.textContent = q[7](val);\n        tick();\n      }\n      rg.addEventListener('input', () => { if (locked) return; val = +rg.value; vl.textContent = qs[i][7](val); });\n      function lock() {\n        if (locked) return; locked = true; ok.disabled = true; const q = qs[i], pts = 250 * Math.max(0, 1 - Math.abs(val - q[2]) / q[6]); sum += pts;\n        tr.textContent = `Richtig: ${q[7](q[2])} · +${Math.round(pts)} Punkte`; c.vib(15); c.after(1500, () => { i++; show(); });\n      }\n      ok.addEventListener('pointerdown', e => { e.preventDefault(); lock(); });\n      function tick() {\n        if (locked) return; const left = T - (performance.now() - t0);\n        c.hud(`Frage ${i + 1}/${N}`, Math.max(0, Math.ceil(left / 1000)) + ' s', Math.max(0, left / T));\n        if (left <= 0) return lock(); c.after(100, tick);\n      }\n      show();\n    },\n  });\n\n  // 8 ---------------------------------------------------------------- Blasmusik-Merker\n  add({\n    id: 'blasmusik', name: 'Blasmusik-Merker', em: '🎺', color: '#ff8fa3', secs: 50,\n    rule: 'Die Kapelle spielt eine Folge vor. Spiele sie nach. Jede Runde wird sie einen Ton länger.',\n    run(c) {\n      const COL = ['#e8433f', '#ffb21a', '#2f9e5b', '#1f58c7'], EM = ['🎺', '🎷', '🥁', '🎻'], FQ = [330, 392, 494, 587], MAXR = 10;\n      const seq = Array.from({ length: 14 }, () => Math.floor(c.rng() * 4));\n      let round = 0, input = 0, accept = false;\n      c.el.innerHTML = '<div class=\"say\" id=\"sy\"></div><div class=\"pads\" id=\"pd\"></div>';\n      const sy = c.el.querySelector('#sy'), pd = c.el.querySelector('#pd');\n      const pads = COL.map((col, k) => { const b = document.createElement('button'); b.className = 'pad'; b.style.setProperty('--pc', col); b.textContent = EM[k]; b.setAttribute('aria-label', 'Instrument ' + (k + 1)); b.addEventListener('pointerdown', e => { e.preventDefault(); press(k); }); pd.appendChild(b); return b; });\n      const lit = (k, ms) => { pads[k].classList.add('lit'); c.tone(FQ[k], ms); c.after(ms, () => pads[k].classList.remove('lit')); };\n      function play() {\n        accept = false; input = 0; round++; if (round > MAXR) return c.finish(1000, 'Alle 10 Runden geschafft!');\n        c.hud(`Runde ${round}/${MAXR}`, '', (round - 1) / MAXR); sy.textContent = 'Zuhören …';\n        for (let i = 0; i < round; i++) c.after(800 + i * 650, () => lit(seq[i], 420));\n        c.after(800 + round * 650, () => { sy.textContent = 'Jetzt du!'; accept = true; });\n      }\n      function press(k) {\n        if (!accept) return; lit(k, 200);\n        if (k !== seq[input]) { accept = false; sy.textContent = 'Falsch!'; c.vib(120); const done = round - 1; return c.after(900, () => c.finish(done * 100, `${done} Runden geschafft`)); }\n        input++; if (input === round) { accept = false; sy.textContent = 'Richtig!'; c.after(800, play); }\n      }\n      play();\n    },\n  });\n\n  // 9 ---------------------------------------------------------------- Bedienung rechnen\n  const ITEMS = [['Maß', 14.5], ['Hendl', 13], ['Brezn', 5], ['Radler', 13.5], ['Weißwurst', 4], ['Obazda', 9.5], ['Limo', 11]];\n  add({\n    id: 'rechnen', name: 'Bedienung rechnen', em: '🧮', color: '#c5e063', secs: 30,\n    rule: 'Die Rechnung stimmt nur, wenn du richtig addierst. 25 Sekunden: richtig gibt Punkte, falsch kostet.',\n    run(c) {\n      const TOTAL = 25000;\n      const qs = Array.from({ length: 14 }, () => {\n        const [a, b] = shuffle(c.rng, ITEMS); const na = 1 + Math.floor(c.rng() * 3), nb = 1 + Math.floor(c.rng() * 3);\n        const sum = na * a[1] + nb * b[1];\n        const wrongs = shuffle(c.rng, [-3, -1.5, -1, -0.5, 0.5, 1, 1.5, 3, 4.5]).slice(0, 2).map(d => sum + d);\n        return { l: `${na}× ${a[0]} à ${eur(a[1])}<br>${nb}× ${b[0]} à ${eur(b[1])}`, opts: shuffle(c.rng, [{ v: sum, ok: true }, ...wrongs.map(v => ({ v, ok: false }))]) };\n      });\n      let i = 0, pts = 0, right = 0, wrong = 0, locked = false, started = performance.now();\n      c.el.innerHTML = '<div class=\"sumq\"><div class=\"l\" id=\"ql\"></div><div class=\"t\">Wie viel kostet das zusammen?</div></div><div class=\"answers\" id=\"ga\"></div>';\n      const ql = c.el.querySelector('#ql'), ga = c.el.querySelector('#ga');\n      function show() {\n        const q = qs[i % qs.length]; locked = false; ql.innerHTML = q.l; ga.innerHTML = '';\n        q.opts.forEach(o => { const b = document.createElement('button'); b.className = 'ans'; b.textContent = eur(o.v); b.addEventListener('pointerdown', e => { e.preventDefault(); if (locked) return; locked = true; if (o.ok) { right++; pts += 110; b.classList.add('right'); c.vib(10); } else { wrong++; pts = Math.max(0, pts - 40); b.classList.add('wrong'); c.vib(60); } c.after(o.ok ? 180 : 450, () => { i++; show(); }); }); ga.appendChild(b); });\n      }\n      function tick() {\n        const left = TOTAL - (performance.now() - started); c.hud(`${right} richtig`, Math.max(0, Math.ceil(left / 1000)) + ' s', Math.max(0, left / TOTAL));\n        if (left <= 0) { locked = true; return c.finish(clamp(pts, 0, 1000), `${right} richtig, ${wrong} falsch`); } c.raf(tick);\n      }\n      show(); c.raf(tick);\n    },\n  });\n\n  // 10 --------------------------------------------------------------- Hau den Lukas\n  add({\n    id: 'lukas', name: 'Hau den Lukas', em: '🔨', color: '#ff9a3c', secs: 25,\n    rule: 'Der Balken schwingt hoch und runter. Schlage zu, wenn er ganz oben ist. Drei Schläge, sie werden schneller.',\n    run(c) {\n      const S = 3, speeds = [0.85, 1.15, 1.5], phase = Array.from({ length: S }, () => c.rng());\n      let swing = 0, sum = 0, t0 = 0, running = false, best = 0;\n      c.el.innerHTML = '<div class=\"lukas\"><div class=\"tower\"><div class=\"glow\" id=\"gw\"></div><div class=\"mk\" id=\"mk\"></div></div><div class=\"side\"><div class=\"bell\" id=\"bl\">🔔</div><div class=\"info\" id=\"inf\"></div></div></div><button class=\"btn gap\" id=\"hm\">Zuschlagen</button>';\n      const mk = c.el.querySelector('#mk'), gw = c.el.querySelector('#gw'), bl = c.el.querySelector('#bl'), inf = c.el.querySelector('#inf'), hm = c.el.querySelector('#hm');\n      const posAt = (now) => { const x = ((now - t0) / 1000 * speeds[swing] + phase[swing]) % 2; return 1 - Math.abs(x - 1) * 1; };\n      function begin() { if (swing >= S) return c.finish(clamp(Math.round(sum), 0, 1000), `Bester Schlag ${Math.round(best * 100)} %`); t0 = performance.now(); running = true; hm.disabled = false; inf.textContent = `Schlag ${swing + 1}/${S}`; c.hud(`Schlag ${swing + 1}/${S}`, '', swing / S); c.raf(frame); }\n      function frame() { if (!running) return; const p = posAt(performance.now()); mk.style.bottom = `calc(${p * 100}% - ${p * 6}px)`; gw.style.height = p * 100 + '%'; c.raf(frame); }\n      hm.addEventListener('pointerdown', e => {\n        e.preventDefault(); if (!running) return; running = false; hm.disabled = true;\n        const p = posAt(performance.now()), pts = 333.4 * Math.pow(p, 3); sum += pts; best = Math.max(best, p);\n        mk.style.bottom = `calc(${p * 100}% - ${p * 6}px)`; gw.style.height = p * 100 + '%'; inf.textContent = `${Math.round(p * 100)} %`; c.vib(40);\n        if (p > 0.93) { bl.classList.remove('ring'); void bl.offsetWidth; bl.classList.add('ring'); c.tone(880, 500); }\n        swing++; c.after(1300, begin);\n      });\n      begin();\n    },\n  });\n\n  // ---------------------------------------------------------------- Runner\n  function createCtx(el, seedBase, onFinish, onHud) {\n    const timers = new Set(), cleans = []; let rafId = 0, rafFns = new Set(), over = false, ac = null;\n    const ctx = {\n      el, rng: mulberry32(seedBase),\n      hud: (l, r, p) => onHud(l, r, p),\n      after(ms, fn) { const id = setTimeout(() => { timers.delete(id); if (!over) fn(); }, ms); timers.add(id); return () => { clearTimeout(id); timers.delete(id); }; },\n      every(ms, fn) { const id = setInterval(() => { if (!over) fn(); }, ms); timers.add(id); return () => clearInterval(id); },\n      raf(fn) { rafFns.add(fn); if (!rafId) rafId = requestAnimationFrame(pump); },\n      onClean(fn) { cleans.push(fn); },\n      vib(ms) { try { navigator.vibrate && navigator.vibrate(ms); } catch {} },\n      tone(freq, ms) { try { ac = ac || new (window.AudioContext || window.webkitAudioContext)(); const o = ac.createOscillator(), g = ac.createGain(); o.type = 'triangle'; o.frequency.value = freq; g.gain.value = 0.12; o.connect(g); g.connect(ac.destination); o.start(); g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + ms / 1000); o.stop(ac.currentTime + ms / 1000 + 0.02); } catch {} },\n      finish(points, text) { if (over) return; ctx.stop(); onFinish(clamp(Math.round(points), 0, 1000), text || ''); },\n      stop() { over = true; timers.forEach(id => { clearTimeout(id); clearInterval(id); }); timers.clear(); rafFns.clear(); cancelAnimationFrame(rafId); rafId = 0; cleans.forEach(f => f()); cleans.length = 0; try { ac && ac.state !== 'closed' && ac.close().catch(() => {}); } catch {} },\n    };\n    function pump() { rafId = 0; const fns = [...rafFns]; rafFns.clear(); for (const f of fns) { if (!over) f(performance.now()); } }   // c.raf() innerhalb von f plant den nächsten Frame selbst\n    return ctx;\n  }\n  function runGame(id, seed, el, onFinish, onHud) {\n    const g = GAMES.find(x => x.id === id), idx = GAMES.indexOf(g);\n    const ctx = createCtx(el, (Number(seed) >>> 0) ^ ((idx + 1) * 0x9E3779B1), onFinish, onHud);\n    try { g.run(ctx); } catch (e) { console.error(e); ctx.stop(); onFinish(0, 'Fehler im Spiel'); }\n    return ctx;\n  }\n  window.WIESN = { GAMES, runGame, esc, num };\n})();\n", "app.js": "'use strict';\n(() => {\n  const { GAMES, runGame, esc, num } = window.WIESN;\n  const API = '/api', deviceKey = 'wiesn-device-id-v2', tokenKey = 'wiesn-token-v4';\n  const $ = s => document.querySelector(s), app = $('#app'), layer = $('#layer');\n  const store = { get: k => { try { return localStorage.getItem(k) || ''; } catch { return ''; } }, set: (k, v) => { try { localStorage.setItem(k, v); } catch {} } };\n  const deviceId = store.get(deviceKey) || (() => { const id = 'd_' + Math.random().toString(36).slice(2) + Date.now().toString(36); store.set(deviceKey, id); return id; })();\n  let token = store.get(tokenKey), S = { players: [], duels: {}, finished: false, me: null };\n  let screen = 'boot', tab = 'games', eventSource = null;\n  let run = null;                         // laufendes Spiel { ctx, gameId, seed, duelId, oppId }\n  let drawCtl = null;                     // Gegner-Würfeln { gameId, exclude, cancelled }\n  let pendingChallenge = null;            // eigene offene Herausforderung { id, gameId, oppId }\n  let queuedIncoming = null;              // Herausforderung, die während eines Spiels eintraf\n  const startedDuels = new Set(), resolvedDuels = new Set();\n  const game = id => GAMES.find(g => g.id === id);\n  const player = id => S.players.find(p => p.id === id);\n  const me = () => player(S.me);\n  const fmt = n => num(n);\n  const sorted = () => [...S.players].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));\n  const placeOf = id => sorted().findIndex(p => p.id === id) + 1;\n\n  // ---------------------------------------------------------------- Netzwerk\n  async function api(path, body = {}) {\n    const payload = { ...body, deviceId, token }; if (S.me && !payload.playerId) payload.playerId = S.me;\n    const r = await fetch(API + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });\n    const data = await r.json().catch(() => ({ ok: false, error: 'Ungültige Serverantwort' }));\n    if (!r.ok || data.ok === false) throw new Error(data.error || 'Serverfehler');\n    return data;\n  }\n  function applyServer(st) { if (!st) return; const m = S.me; S = st; S.me = m && S.players.some(p => p.id === m) ? m : null; }\n  function adopt(d) { token = d.token; store.set(tokenKey, token); if (d.seq) lastEv = Math.max(lastEv, d.seq); S = d.state; S.me = d.player.id; }\n  function setNet(on) { const n = $('#net'); n.className = 'net ' + (on || !S.me ? 'on' : 'off'); n.textContent = on ? 'live' : 'offline'; }\n  let toastT = null;\n  function toast(msg) { const t = $('#toast'); t.textContent = msg; t.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('show'), 2600); }\n\n  let refreshT = null;\n  function refresh() {\n    clearTimeout(refreshT);\n    refreshT = setTimeout(() => {\n      if (!S.me) { if (screen !== 'join' && screen !== 'boot') { screen = 'join'; render(); } return; }\n      if (S.finished && !['finish', 'play', 'intro', 'dwait', 'result'].includes(screen)) { screen = 'finish'; return render(); }\n      if (screen === 'home' || screen === 'finish') { const y = window.scrollY; render(); window.scrollTo(0, y); }\n    }, 120);\n  }\n\n  let lastEv = 0, lastAct = Date.now(), pollTimer = null, sseOpen = false, errTimer = null;\n  function dispatch(name, data, id) {\n    if (id) { if (id <= lastEv) return; lastEv = id; }\n    if (name === 'duel:incoming') incoming(data);\n    else if (name === 'duel:accepted') accepted(data);\n    else if (name === 'duel:declined') challengeEnded(`${player(data.toId)?.name || 'Dein Gegner'} hat abgelehnt. Würfle neu.`);\n    else if (name === 'duel:expired') challengeEnded('Keine Antwort. Würfle neu.');\n    else if (name === 'duel:withdrawn') { $('#incoming')?.remove(); if (queuedIncoming?.id === data.id) queuedIncoming = null; }\n    else if (name === 'duel:result') duelResult(data);\n  }\n  function startPoll() {\n    if (pollTimer || !S.me) return;\n    const tick = async () => { if (!S.me) return; try { const d = await api('/poll', { after: lastEv }); setNet(true); applyServer(d.state); for (const ev of d.events) dispatch(ev.event, ev.data, ev.id); refresh(); } catch { setNet(false); } };\n    tick(); pollTimer = setInterval(tick, 2000);\n  }\n  function stopPoll() { clearInterval(pollTimer); pollTimer = null; }\n  function connect() {\n    if (eventSource) eventSource.close();\n    lastAct = Date.now(); sseOpen = false;\n    const es = new EventSource('/events?playerId=' + encodeURIComponent(S.me || '')); eventSource = es;\n    es.addEventListener('state', e => { lastAct = Date.now(); sseOpen = true; stopPoll(); applyServer(JSON.parse(e.data)); setNet(true); refresh(); });\n    es.addEventListener('ping', () => { lastAct = Date.now(); });\n    for (const n of ['duel:incoming', 'duel:accepted', 'duel:declined', 'duel:expired', 'duel:withdrawn', 'duel:result'])\n      es.addEventListener(n, e => { lastAct = Date.now(); dispatch(n, JSON.parse(e.data), Number(e.lastEventId) || 0); });\n    es.onopen = () => { clearTimeout(errTimer); errTimer = null; setNet(true); };\n    es.onerror = () => { if (!pollTimer) setNet(false); sseOpen = false; if (!errTimer) errTimer = setTimeout(() => { errTimer = null; if (!sseOpen) startPoll(); }, 4000); };\n  }\n  setInterval(() => { if (S.me && eventSource && Date.now() - lastAct > 50000) { startPoll(); connect(); } }, 10000);\n\n  // ---------------------------------------------------------------- Kleine UI-Helfer\n  function overlay(html, cls = '') { layer.innerHTML = `<div class=\"scrim ${cls}\">${html}</div>`; return layer.firstElementChild; }\n  const closeOverlay = () => { layer.innerHTML = ''; };\n  function confirmBox(title, text, okLabel, danger) {\n    return new Promise(res => {\n      const o = overlay(`<div class=\"modal\" role=\"dialog\" aria-modal=\"true\"><h2>${esc(title)}</h2><p>${esc(text)}</p><div class=\"row gap\"><button class=\"btn light\" data-v=\"0\">Zurück</button><button class=\"btn ${danger ? 'red' : ''}\" data-v=\"1\">${esc(okLabel)}</button></div></div>`, 'mid');\n      o.addEventListener('click', e => { const v = e.target.closest('[data-v]'); if (v) { closeOverlay(); res(v.dataset.v === '1'); } });\n    });\n  }\n  const nav = () => `<nav class=\"nav\" aria-label=\"Hauptmenü\"><div><button data-nav=\"games\" ${tab === 'games' ? 'aria-current=\"page\"' : ''}>🎮 Spiele</button><button data-nav=\"rank\" ${tab === 'rank' ? 'aria-current=\"page\"' : ''}>🏆 Rangliste</button></div></nav>`;\n\n  // ---------------------------------------------------------------- Bildschirme\n  function render() {\n    document.body.classList.toggle('playing', screen === 'play');\n    if (screen === 'join') return joinUI();\n    if (screen === 'home') return homeUI();\n    if (screen === 'finish') return finishUI();\n    if (screen === 'boot') app.innerHTML = '<div class=\"waitbox\"><div class=\"em\">🍻</div><h2>Verbinde …</h2></div>';\n  }\n  function joinUI() {\n    app.innerHTML = `<div class=\"hero\"><span class=\"krug\">🍻</span><h1>Wiesn Team Challenge</h1><p>10 kurze Spiele. Alleine oder im Duell gegen jemanden vom Tisch.</p></div>\n      <form class=\"card join\" id=\"jf\"><label for=\"nm\">Wie heißt du?</label><input id=\"nm\" type=\"text\" maxlength=\"20\" autocomplete=\"nickname\" placeholder=\"Dein Name\" required><button class=\"btn gap\" type=\"submit\">Rein ins Festzelt</button></form>\n      <p class=\"rules\">Jedes Spiel einmal <b>solo</b> und einmal im <b>Duell</b>. Wer ein Duell gewinnt, bekommt <b>+50 Punkte</b>. Dein Gegner wird zufällig ausgewählt.</p>`;\n    $('#jf').addEventListener('submit', async e => {\n      e.preventDefault(); const name = $('#nm').value.trim(); if (!name) return toast('Bitte gib deinen Namen ein.');\n      try { adopt(await api('/register', { name })); screen = 'home'; tab = 'games'; render(); connect(); } catch (er) { toast(er.message); }\n    });\n  }\n  function homeUI() {\n    const m = me(); if (!m) return;\n    const head = `<header class=\"top\"><div class=\"ava\" aria-hidden=\"true\">${m.avatar}</div><div class=\"who\"><b>${esc(m.name)}</b><span>${esc(m.charName)}</span></div><div class=\"pts\"><b>${fmt(m.score)}</b><span>Platz ${placeOf(m.id)} von ${S.players.length}</span></div></header>`;\n    let body;\n    if (tab === 'games') {\n      const left = GAMES.reduce((n, g) => n + (m.soloGames.includes(g.id) ? 0 : 1) + (m.duelGames.includes(g.id) ? 0 : 1), 0);\n      body = `<h2 class=\"sec-title\">Such dir ein Spiel aus</h2><p class=\"sec-sub\">${left ? `Noch ${left} von 20 Runden offen.` : 'Alle 20 Runden gespielt. Stark!'}</p><div class=\"grid\">${GAMES.map(g => {\n        const s = m.soloGames.includes(g.id), d = m.duelGames.includes(g.id);\n        return `<button class=\"tile ${s && d ? 'all' : ''}\" data-game=\"${g.id}\" style=\"--c:${g.color}\"><div><div class=\"em\" aria-hidden=\"true\">${g.em}</div><h3>${esc(g.name)}</h3><div class=\"dur\">ca. ${g.secs} Sek.</div></div><div class=\"marks\"><span class=\"mark ${s ? 'done' : ''}\">${s ? '✓ ' : ''}Solo</span><span class=\"mark ${d ? 'done' : ''}\">${d ? '✓ ' : ''}Duell</span></div></button>`;\n      }).join('')}</div>`;\n    } else body = rankBody();\n    app.innerHTML = head + body + nav();\n  }\n  function rankBody() {\n    const list = sorted(), m = me();\n    const rows = list.map((p, i) => `<li class=\"${p.id === S.me ? 'me' : ''} ${i === 0 ? 'top1' : ''}\"><span class=\"n\">${i + 1}</span><span class=\"a\" aria-hidden=\"true\">${p.avatar}</span><span class=\"nm\"><span class=\"dot ${p.online ? 'on' : ''}\" title=\"${p.online ? 'online' : 'offline'}\"></span>${esc(p.name)}<small>${esc(p.charName)}</small></span><span class=\"p\">${fmt(p.score)}</span></li>`).join('');\n    const host = m && S.hostId === m.id ? `<div class=\"host\"><p>Du bist Spielleiter.</p><button class=\"btn light\" data-act=\"end\">Event beenden</button><button class=\"btn red\" data-act=\"reset\">Neue Runde (alles löschen)</button></div>` : '';\n    return `<h2 class=\"sec-title\">Rangliste</h2><ol class=\"rank\">${rows || ''}</ol>${host}`;\n  }\n  function finishUI() {\n    const list = sorted(), top = list.slice(0, 3), m = me();\n    const pod = (p, c) => p ? `<div class=\"pl ${c}\"><div class=\"a\">${p.avatar}</div>${esc(p.name)}<div class=\"blk\">${c === 'p1' ? 1 : c === 'p2' ? 2 : 3}</div></div>` : '<div></div>';\n    app.innerHTML = `<div class=\"hero\"><h1>Das war die Wiesn!</h1><p>${top[0] ? `${esc(top[0].name)} gewinnt mit ${fmt(top[0].score)} Punkten.` : ''}</p></div><div class=\"podium\">${pod(top[1], 'p2')}${pod(top[0], 'p1')}${pod(top[2], 'p3')}</div><ol class=\"rank\">${list.map((p, i) => `<li class=\"${p.id === S.me ? 'me' : ''}\"><span class=\"n\">${i + 1}</span><span class=\"a\">${p.avatar}</span><span class=\"nm\">${esc(p.name)}<small>${esc(p.charName)}</small></span><span class=\"p\">${fmt(p.score)}</span></li>`).join('')}</ol>${m && S.hostId === m.id ? '<div class=\"host\"><button class=\"btn red\" data-act=\"reset\">Neue Runde (alles löschen)</button></div>' : ''}`;\n  }\n\n  // Klicks (Delegation)\n  document.addEventListener('click', async e => {\n    const n = e.target.closest('[data-nav]'); if (n) { tab = n.dataset.nav; window.scrollTo(0, 0); return render(); }\n    const t = e.target.closest('[data-game]'); if (t) return gameSheet(t.dataset.game);\n    const a = e.target.closest('[data-act]'); if (!a) return;\n    if (a.dataset.act === 'end' && await confirmBox('Event beenden?', 'Danach sehen alle die Endrangliste.', 'Beenden', true)) { try { applyServer((await api('/event/end')).state); screen = 'finish'; render(); } catch (er) { toast(er.message); } }\n    if (a.dataset.act === 'reset' && await confirmBox('Alles löschen?', 'Der gesamte Spielstand wird für ALLE gelöscht und eine neue Runde beginnt.', 'Löschen', true)) { try { applyServer((await api('/event/reset')).state); S.me = null; screen = 'join'; render(); } catch (er) { toast(er.message); } }\n  });\n\n  // ---------------------------------------------------------------- Spiel wählen: Solo oder Duell\n  function gameSheet(id) {\n    const g = game(id), m = me(), s = m.soloGames.includes(id), d = m.duelGames.includes(id);\n    const o = overlay(`<div class=\"sheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"${esc(g.name)}\"><div class=\"em\" aria-hidden=\"true\">${g.em}</div><h2>${esc(g.name)}</h2><p>${esc(g.rule)}</p>\n      <button class=\"btn opt\" data-go=\"solo\" ${s ? 'disabled' : ''}>${s ? '✓ Solo schon gespielt' : 'Solo spielen'}<small>${s ? 'Jedes Spiel zählt einmal solo' : 'Du spielst allein, ca. ' + g.secs + ' Sekunden'}</small></button>\n      <button class=\"btn blue opt\" data-go=\"duel\" ${d ? 'disabled' : ''}>${d ? '✓ Duell schon gespielt' : '🎲 Duell: Gegner auslosen'}<small>${d ? 'Jedes Spiel zählt einmal im Duell' : 'Zufällige Person, Sieger bekommt +50'}</small></button>\n      <button class=\"btn light\" data-go=\"close\">Zurück</button></div>`);\n    o.addEventListener('click', e => {\n      if (e.target === o) return closeOverlay();\n      const b = e.target.closest('[data-go]'); if (!b) return; const v = b.dataset.go;\n      closeOverlay();\n      if (v === 'solo') startSolo(id); else if (v === 'duel') startDraw(id);\n    });\n  }\n  async function startSolo(id) {\n    try { const d = await api('/game/start', { gameId: id }); applyServer(d.state); introUI({ gameId: id, seed: d.seed, duelId: null }); } catch (e) { toast(e.message); }\n  }\n\n  // ---------------------------------------------------------------- Gegner auslosen\n  function startDraw(id) {\n    drawCtl = { gameId: id, exclude: [], cancelled: false, busy: false };\n    screen = 'draw'; window.scrollTo(0, 0);\n    const g = game(id);\n    app.innerHTML = `<div class=\"draw\"><h2>${g.em} ${esc(g.name)}</h2><p class=\"sub\">Wer ist dein Gegner? Der Zufall entscheidet.</p><div class=\"reel spin\" id=\"reel\" aria-hidden=\"true\">🎲</div><div class=\"cand\" id=\"cand\" aria-live=\"polite\"></div><div class=\"btns\" id=\"dbtns\"></div></div>`;\n    roll();\n  }\n  async function roll() {\n    const c = drawCtl; if (!c || c.busy) return; c.busy = true;\n    const reel = $('#reel'), cand = $('#cand'), btns = $('#dbtns'); if (!reel) return;\n    reel.className = 'reel spin'; reel.textContent = '🎲'; cand.innerHTML = '<div class=\"ghost\">Würfel rollt …</div>'; btns.innerHTML = '<button class=\"btn light\" data-d=\"back\">Abbrechen</button>';\n    let res;\n    try { res = await api('/duels/draw', { gameId: c.gameId, exclude: c.exclude }); }\n    catch (e) { c.busy = false; reel.className = 'reel'; reel.textContent = '🤷'; cand.innerHTML = `<div class=\"ghost\">${esc(e.message)}</div>`; btns.innerHTML = '<button class=\"btn\" data-d=\"retry\">Nochmal versuchen</button><button class=\"btn light\" data-d=\"back\">Zurück</button>'; return; }\n    const pool = res.pool.length > 1 ? res.pool : [res.candidate, { avatar: '🎲' }];\n    let i = 0; const steps = 15;\n    const step = () => {\n      if (c.cancelled) return;\n      if (i >= steps) {\n        c.busy = false; c.exclude.push(res.candidate.id); c.current = res.candidate;\n        reel.className = 'reel land'; reel.textContent = res.candidate.avatar;\n        cand.innerHTML = `<div class=\"nm\">${esc(res.candidate.name)}</div><div class=\"meta\">${esc(res.candidate.charName)} · ${fmt(res.candidate.score)} Punkte${res.candidate.online ? '' : ' · gerade offline'}</div>`;\n        btns.innerHTML = `<button class=\"btn\" data-d=\"go\">Herausfordern</button><button class=\"btn blue\" data-d=\"again\">🎲 Neu würfeln</button><button class=\"btn light\" data-d=\"back\">Abbrechen</button>`;\n        try { navigator.vibrate && navigator.vibrate([30, 40, 60]); } catch {}\n        return;\n      }\n      reel.textContent = pool[(i * 7 + Math.floor(Math.random() * pool.length)) % pool.length].avatar; i++;\n      setTimeout(step, 60 + i * i * 2.4);\n    };\n    step();\n  }\n  app.addEventListener('click', async e => {\n    const b = e.target.closest('[data-d]'); if (!b || !drawCtl) return; const v = b.dataset.d;\n    if (v === 'back') { drawCtl.cancelled = true; drawCtl = null; screen = 'home'; return render(); }\n    if (v === 'retry' || v === 'again') { drawCtl.busy = false; return roll(); }\n    if (v === 'go') {\n      const c = drawCtl.current; if (!c) return;\n      try {\n        const d = await api('/duels/request', { toId: c.id, gameId: drawCtl.gameId });\n        pendingChallenge = { id: d.duel.id, gameId: drawCtl.gameId, oppId: c.id }; drawCtl = null; waitUI();\n      } catch (er) { toast(er.message); drawCtl.busy = false; roll(); }\n    }\n  });\n  function waitUI() {\n    screen = 'wait'; const p = pendingChallenge, opp = player(p.oppId), g = game(p.gameId);\n    app.innerHTML = `<div class=\"waitbox\"><div class=\"em\">${opp ? opp.avatar : '⚔️'}</div><h2>${esc(opp ? opp.name : 'Dein Gegner')} ist dran</h2><p>${g.em} ${esc(g.name)}. Das Duell startet, sobald angenommen wird.</p><button class=\"btn light\" id=\"wc\">Anfrage zurückziehen</button></div>`;\n    $('#wc').addEventListener('click', async () => { try { await api('/duels/cancel', { duelId: p.id }); } catch {} pendingChallenge = null; startDraw(p.gameId); });\n  }\n  function challengeEnded(msg) { if (!pendingChallenge || screen !== 'wait') return; const g = pendingChallenge.gameId; pendingChallenge = null; toast(msg); startDraw(g); }\n\n  // ---------------------------------------------------------------- Eingehende Herausforderung\n  function incoming(duel) {\n    if (screen === 'play') { queuedIncoming = duel; return; }\n    showIncoming(duel);\n  }\n  function showIncoming(duel) {\n    const g = game(duel.gameId), from = player(duel.fromId); if (!g || !from) return;\n    queuedIncoming = null; $('#incoming')?.remove();\n    const o = document.createElement('div'); o.id = 'incoming'; o.className = 'scrim mid'; o.style.zIndex = 60;\n    o.innerHTML = `<div class=\"modal\" role=\"alertdialog\" aria-modal=\"true\"><div class=\"em\">${from.avatar}</div><h2>${esc(from.name)} fordert dich heraus!</h2><p><b>${g.em} ${esc(g.name)}</b><br>${esc(g.rule)}</p><div class=\"row gap\"><button class=\"btn light\" data-r=\"0\">Ablehnen</button><button class=\"btn\" data-r=\"1\">Annehmen</button></div></div>`;\n    document.body.appendChild(o);\n    try { navigator.vibrate && navigator.vibrate([60, 60, 60]); } catch {}\n    o.addEventListener('click', async e => {\n      const b = e.target.closest('[data-r]'); if (!b) return; o.remove();\n      try { const d = await api('/duels/respond', { duelId: duel.id, accept: b.dataset.r === '1' }); applyServer(d.state); if (b.dataset.r === '1') accepted(d.duel); } catch (er) { toast(er.message); }\n    });\n  }\n  function accepted(duel) {\n    pendingChallenge = null; if (startedDuels.has(duel.id) || resolvedDuels.has(duel.id)) return; startedDuels.add(duel.id);\n    drawCtl && (drawCtl.cancelled = true); drawCtl = null; closeOverlay(); $('#incoming')?.remove();\n    if (run) return;                        // sollte nicht passieren\n    introUI({ gameId: duel.gameId, seed: duel.seed, duelId: duel.id, oppId: duel.fromId === S.me ? duel.toId : duel.fromId });\n  }\n\n  // ---------------------------------------------------------------- Intro, Spiel, Ergebnis\n  function introUI(job) {\n    screen = 'intro'; window.scrollTo(0, 0); const g = game(job.gameId), opp = job.oppId ? player(job.oppId) : null, m = me();\n    app.innerHTML = `<div class=\"intro\"><div class=\"big\" aria-hidden=\"true\">${g.em}</div><h2>${esc(g.name)}</h2>${opp ? `<div class=\"vs\"><span>${m.avatar} ${esc(m.name)}</span><i>VS</i><span>${opp.avatar} ${esc(opp.name)}</span></div>` : ''}<p class=\"rule\">${esc(g.rule)}</p>${opp ? '<p class=\"muted on-dark\" style=\"font-weight:700;margin:-8px 0 18px\">Ihr bekommt dieselben Aufgaben. Wer mehr Punkte hat, gewinnt +50.</p>' : ''}<button class=\"btn\" id=\"go\">Los geht’s</button><button class=\"btn light\" id=\"ab\">${opp ? 'Aufgeben' : 'Zurück'}</button></div>`;\n    $('#go').addEventListener('click', () => play(job));\n    $('#ab').addEventListener('click', () => abort(job));\n  }\n  function play(job) {\n    screen = 'play'; document.body.classList.add('playing'); const g = game(job.gameId);\n    layer.innerHTML = `<div class=\"play\" id=\"pl\"><div class=\"hud\"><button class=\"x\" id=\"px\" aria-label=\"Spiel verlassen\">✕</button><div class=\"gname\" aria-label=\"${esc(g.name)}\">${g.em}<span>${esc(g.name)}</span></div><div class=\"hv\" id=\"hl\"></div><div class=\"hv\" id=\"hr\"></div></div><div class=\"bar\"><i id=\"hb\"></i></div><div class=\"stage\" id=\"stg\"></div></div>`;\n    const hl = $('#hl'), hr = $('#hr'), hb = $('#hb'), stg = $('#stg');\n    const onHud = (l, r, p) => { hl.textContent = l || ''; hl.style.display = l ? '' : 'none'; hr.textContent = r || ''; hr.style.display = r ? '' : 'none'; if (typeof p === 'number') hb.style.transform = `scaleX(${Math.max(0, Math.min(1, p))})`; };\n    job.ctxHolder = runGame(job.gameId, job.seed, stg, (pts, text) => submit(job, pts, text), onHud);\n    run = job;\n    $('#px').addEventListener('click', async () => { if (await confirmBox(job.duelId ? 'Duell aufgeben?' : 'Spiel verlassen?', job.duelId ? 'Das zählt als Niederlage mit 0 Punkten.' : 'Dieser Versuch zählt nicht. Du kannst das Spiel später noch einmal spielen.', job.duelId ? 'Aufgeben' : 'Verlassen', true)) abort(job); });\n  }\n  function endPlay() { if (run?.ctxHolder) run.ctxHolder.stop(); run = null; layer.innerHTML = ''; document.body.classList.remove('playing'); }\n  async function abort(job) {\n    endPlay();\n    try { const d = await api('/game/cancel', { duelId: job.duelId || null }); applyServer(d.state); if (d.result) return duelResult(d.result, true); } catch {}\n    toast(job.duelId ? 'Duell aufgegeben.' : 'Spiel abgebrochen.'); goHome();\n  }\n  function goHome() { screen = 'home'; tab = 'games'; render(); window.scrollTo(0, 0); if (queuedIncoming) showIncoming(queuedIncoming); }\n  async function submit(job, pts, text) {\n    endPlay(); screen = 'result';\n    app.innerHTML = `<div class=\"waitbox\"><div class=\"em\">⏳</div><h2>Ergebnis wird gespeichert …</h2></div>`;\n    let d, tries = 0;\n    for (;;) { try { d = await api('/game/finish', { gameId: job.gameId, points: pts, duelId: job.duelId || null }); break; } catch (e) { if (++tries > 4 || /Kein laufendes/.test(e.message)) { toast(e.message); return goHome(); } await new Promise(r => setTimeout(r, 1200)); } }\n    applyServer(d.state);\n    if (d.result) return duelResult(d.result, true);\n    if (d.pending) { if (resolvedDuels.has(job.duelId)) return; return dwaitUI(job, pts, text); }\n    if (d.already) { toast('Dieses Ergebnis wurde schon gewertet.'); return goHome(); }\n    soloResultUI(job, d.points ?? pts, text);\n  }\n  function countUp(el, to, ms = 900) { const t0 = performance.now(); (function f(t) { const k = Math.min(1, (t - t0) / ms); el.textContent = fmt(Math.round(to * (1 - Math.pow(1 - k, 3)))); if (k < 1 && el.isConnected) requestAnimationFrame(f); })(t0); }\n  function soloResultUI(job, pts, text) {\n    screen = 'result'; const g = game(job.gameId), m = me();\n    const verdict = pts >= 800 ? 'Wahnsinn!' : pts >= 550 ? 'Stark!' : pts >= 300 ? 'Solide.' : 'Das geht besser.';\n    app.innerHTML = `<div class=\"result\"><div class=\"em\">${g.em}</div><h2>${verdict}</h2><div class=\"score\"><span id=\"sc\">0</span><small> Punkte</small></div><div class=\"detail\">${esc(text)}</div><p class=\"detail\">Du liegst auf Platz ${placeOf(m.id)} mit ${fmt(m.score)} Punkten.</p><div class=\"btns\"><button class=\"btn\" id=\"back\">Weiter</button></div></div>`;\n    countUp($('#sc'), pts); $('#back').addEventListener('click', goHome);\n  }\n  function dwaitUI(job, pts, text) {\n    screen = 'dwait'; const opp = player(job.oppId), g = game(job.gameId);\n    app.innerHTML = `<div class=\"waitbox\"><div class=\"em\">⏳</div><h2>${fmt(pts)} Punkte</h2><p>${esc(text)}<br>Jetzt spielt noch ${esc(opp ? opp.name : 'dein Gegner')}. Das Ergebnis kommt automatisch.</p><button class=\"btn light\" id=\"hm\">Zu den Spielen (Ergebnis kommt als Meldung)</button></div>`;\n    $('#hm').addEventListener('click', goHome);\n  }\n  function duelResult(r, force) {\n    const mine = r.scores?.[S.me]; if (mine === undefined || resolvedDuels.has(r.duelId)) return; resolvedDuels.add(r.duelId);\n    const oppId = r.fromId === S.me ? r.toId : r.fromId, opp = player(oppId), m = me(), g = game(r.gameId), oppPts = r.scores[oppId];\n    const win = r.winnerId === S.me, draw = r.winnerId === null;\n    if (!force && !['dwait', 'result', 'intro'].includes(screen)) { toast(`${draw ? 'Unentschieden' : win ? 'Duell gewonnen' : 'Duell verloren'} (${fmt(mine)} : ${fmt(oppPts)})`); return; }\n    if (screen === 'play') return;\n    screen = 'result';\n    const side = (p, pts, raw, w) => `<div class=\"side ${w ? 'win' : ''}\"><div class=\"a\">${p ? p.avatar : '❓'}</div><b>${esc(p ? p.name : 'Gegner')}</b><div class=\"v\">${fmt(pts)}</div>${w ? `<div class=\"bn\">inkl. +${r.bonus} Bonus</div>` : '<div class=\"bn\">&nbsp;</div>'}</div>`;\n    const title = draw ? 'Unentschieden' : win ? 'Du hast gewonnen!' : 'Diesmal verloren';\n    const sub = r.forfeit ? (r.forfeit === S.me ? 'Du hast aufgegeben.' : `${esc(opp ? opp.name : 'Dein Gegner')} hat aufgegeben.`) : g.name;\n    app.innerHTML = `<div class=\"result\"><div class=\"em\">${draw ? '🤝' : win ? '🏆' : '😅'}</div><h2>${title}</h2><div class=\"detail\">${g.em} ${esc(sub)}</div><div class=\"versus\">${side(m, mine, r.raw[S.me], win)}${side(opp, oppPts, r.raw[oppId], r.winnerId === oppId)}</div><p class=\"detail\" id=\"ranknote\">Du liegst auf Platz ${placeOf(m.id)} mit ${fmt(m.score)} Punkten.</p><div class=\"btns\"><button class=\"btn\" id=\"back\">Weiter</button></div></div>`;\n    $('#back').addEventListener('click', goHome);\n    fetch(API + '/state').then(x => x.json()).then(d => { applyServer(d.state); const n = $('#ranknote'), mm = me(); if (n && mm) n.textContent = `Du liegst auf Platz ${placeOf(mm.id)} mit ${fmt(mm.score)} Punkten.`; }).catch(() => {});   // das Ergebnis-Ereignis kommt vor dem neuen Gesamtstand\n  }\n\n  // ---------------------------------------------------------------- Start\n  (async function boot() {\n    render();\n    try { adopt(await api('/resume')); screen = S.finished ? 'finish' : 'home'; }\n    catch { try { const r = await fetch(API + '/state'); applyServer((await r.json()).state); } catch { setNet(false); } S.me = null; screen = 'join'; }\n    render(); if (S.me) connect();\n  })();\n})();\n"};   // Oberfläche direkt eingebettet: nur diese eine Datei muss hochgeladen werden
// ---------- State ----------
function empty() {
  return { version: 4, players: [], duels: {}, sessions: {}, hostId: null, finished: false, updatedAt: Date.now() };
}
async function redis(cmd) {
  const r = await fetch(REDIS_URL, { method: 'POST', headers: { Authorization: `Bearer ${REDIS_TOKEN}`, 'Content-Type': 'application/json', 'User-Agent': 'wiesn-team-challenge' }, body: JSON.stringify(cmd), signal: AbortSignal.timeout(6000) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || j.error) throw new Error(j.error || 'HTTP ' + r.status);
  return j.result;
}
let remoteDirty = false, remoteTimer = null, remoteBusy = false;
async function flushRemote() {
  clearTimeout(remoteTimer); remoteTimer = null;
  if (!USE_REDIS || !remoteDirty || remoteBusy) return;
  remoteBusy = true; remoteDirty = false;
  try { await redis(['SET', REDIS_KEY, JSON.stringify(state)]); }
  catch (e) { remoteDirty = true; console.error('Redis-Speichern fehlgeschlagen:', e.message); remoteTimer = setTimeout(flushRemote, 10000); }
  finally { remoteBusy = false; if (remoteDirty && !remoteTimer) remoteTimer = setTimeout(flushRemote, 1500); }
}
function save() {
  state.updatedAt = Date.now();
  const tmp = DATA + '.tmp';
  try { fs.writeFileSync(tmp, JSON.stringify(state)); fs.renameSync(tmp, DATA); }
  catch (e) { if (!USE_REDIS) console.error('Speichern fehlgeschlagen:', e.message); }
  if (USE_REDIS) { remoteDirty = true; if (!remoteTimer && !remoteBusy) remoteTimer = setTimeout(flushRemote, 1500); }
}
function normalize(raw) {
  const s = Object.assign(empty(), raw);
  s.version = 4;
  for (const p of s.players) { if (!p.token) p.token = secret(); p.soloGames = p.soloGames || []; p.duelGames = p.duelGames || []; p.played = p.played || []; }
  if (!s.hostId && s.players.length) s.hostId = s.players[0].id;
  return s;
}
function load() {
  try { return normalize(JSON.parse(fs.readFileSync(DATA, 'utf8'))); } catch { return empty(); }
}
async function loadRemote() {
  if (!USE_REDIS) return;
  try {
    const v = await redis(['GET', REDIS_KEY]);
    if (v) { state = normalize(JSON.parse(v)); console.log(`Spielstand aus Redis geladen (${state.players.length} Spieler).`); }
    else console.log('Redis erreichbar, noch kein gespeicherter Spielstand.');
  } catch (e) { console.error('Redis-Laden fehlgeschlagen – starte mit lokalem/leerem Stand:', e.message); }
}
const secret = () => crypto.randomBytes(16).toString('hex');
const uid = (p) => p + '_' + crypto.randomBytes(7).toString('hex');
let state = load();
const clients = new Set();

const seen = new Map();   // playerId -> letzter Kontakt (für Polling-Handys)
const touch = id => seen.set(id, Date.now());
const isOnline = id => { if (Date.now() - (seen.get(id) || 0) < ONLINE_MS) return true; for (const c of clients) if (c.playerId === id) return true; return false; };

const pub = p => ({ id: p.id, name: p.name, avatar: p.avatar, charName: p.charName, charId: p.charId, score: p.score, soloGames: p.soloGames, duelGames: p.duelGames, played: p.played, online: isOnline(p.id) });
function snapshot() {
  const duels = {};
  for (const d of Object.values(state.duels)) {
    if (d.resulted || ['declined', 'expired', 'cancelled'].includes(d.status)) continue;
    duels[d.id] = { id: d.id, gameId: d.gameId, fromId: d.fromId, toId: d.toId, status: d.status, seed: d.status === 'accepted' ? d.seed : undefined };
  }
  return { version: state.version, players: state.players.map(pub), duels, hostId: state.hostId, finished: state.finished, updatedAt: state.updatedAt };
}

// ---------- Helfer ----------
const getPlayer = id => state.players.find(p => p.id === id);
const clamp = v => Math.max(0, Math.min(MAX_POINTS, Math.round(Number(v) || 0)));
const fail = (status, msg) => Object.assign(new Error(msg), { status });
const randInt = n => crypto.randomInt(n);
const busyDuel = pid => Object.values(state.duels).find(d => !d.resulted && (d.fromId === pid || d.toId === pid) && (d.status === 'pending' || d.status === 'accepted'));

function auth(b) {
  const p = getPlayer(String(b.playerId || ''));
  const t = Buffer.from(String(b.token || ''));
  const real = p && Buffer.from(p.token);
  if (!p || t.length !== real.length || !crypto.timingSafeEqual(t, real)) throw fail(401, 'Nicht angemeldet. Bitte Seite neu laden.');
  touch(p.id);
  return p;
}
function broadcast() {
  const msg = `event: state\ndata: ${JSON.stringify(snapshot())}\n\n`;
  for (const c of clients) { try { c.res.write(msg); } catch { clients.delete(c); } }
}
let evSeq = Date.now(); const inbox = new Map();   // Ereignisse pro Spieler (für SSE-Wiederaufnahme und Polling-Fallback)
function pushPlayer(pid, event, data) {
  const ev = { id: ++evSeq, event, data, at: Date.now() };
  const list = inbox.get(pid) || []; list.push(ev);
  inbox.set(pid, list.filter(e => Date.now() - e.at < 10 * 60 * 1000).slice(-40));
  for (const c of clients) if (c.playerId === pid) { try { c.res.write(`id: ${ev.id}\nevent: ${event}\ndata: ${JSON.stringify(data)}\n\n`); } catch { clients.delete(c); } }
}
function addScore(p, game, points, kind, won) { p.score += points; p.played.push({ game, kind, points, won: !!won, at: Date.now() }); }
function releaseSession(pid) {            // abgebrochenes/verlassenes Solo-Spiel: Versuch zurückgeben
  const s = state.sessions[pid], p = getPlayer(pid);
  if (s && p) p.soloGames = p.soloGames.filter(g => g !== s.gameId);
  delete state.sessions[pid];
}
function resolveDuel(d) {
  if (d.resulted) return d.result;
  d.resulted = true; d.resultAt = Date.now();
  const a = d.scores[d.fromId] ?? 0, b = d.scores[d.toId] ?? 0;
  const winnerId = a === b ? null : (a > b ? d.fromId : d.toId);
  const pa = getPlayer(d.fromId), pb = getPlayer(d.toId);
  const fa = a + (winnerId === d.fromId ? DUEL_BONUS : 0), fb = b + (winnerId === d.toId ? DUEL_BONUS : 0);
  if (pa) addScore(pa, d.gameId, fa, 'duel', winnerId === d.fromId);
  if (pb) addScore(pb, d.gameId, fb, 'duel', winnerId === d.toId);
  d.result = { duelId: d.id, gameId: d.gameId, fromId: d.fromId, toId: d.toId, scores: { [d.fromId]: fa, [d.toId]: fb }, raw: { [d.fromId]: a, [d.toId]: b }, bonus: DUEL_BONUS, winnerId, forfeit: d.forfeit || null };
  pushPlayer(d.fromId, 'duel:result', d.result);
  pushPlayer(d.toId, 'duel:result', d.result);
  return d.result;
}
function submitDuel(d, p, points, forfeit) {
  if (d.scores[p.id] !== undefined) return;
  d.scores[p.id] = forfeit ? 0 : clamp(points);
  if (forfeit) d.forfeit = p.id;
  if (d.scores[d.fromId] !== undefined && d.scores[d.toId] !== undefined) resolveDuel(d);
}
function openDuelFor(p, duelId) {
  const d = state.duels[duelId];
  if (!d || d.status !== 'accepted' || d.resulted || (d.fromId !== p.id && d.toId !== p.id)) return null;
  return d;
}
function candidatesFor(me, g, exclude) {
  const all = state.players.filter(o => o.id !== me.id && !o.duelGames.includes(g) && !busyDuel(o.id) && !exclude.includes(o.id));
  const online = all.filter(o => isOnline(o.id));
  return online.length ? online : all;
}
setInterval(() => {                       // Aufräumen: verfallene Herausforderungen + hängende Duelle
  let changed = false; const now = Date.now();
  for (const d of Object.values(state.duels)) {
    if (d.status === 'pending' && now - d.createdAt > PENDING_TTL) { d.status = 'expired'; changed = true; pushPlayer(d.fromId, 'duel:expired', { id: d.id }); pushPlayer(d.toId, 'duel:withdrawn', { id: d.id }); }
    if (d.status === 'accepted' && !d.resulted && now - d.acceptedAt > DUEL_TTL) { resolveDuel(d); changed = true; }
  }
  if (changed) { save(); broadcast(); }
}, 15000);
setInterval(() => { for (const c of clients) { try { c.res.write('event: ping\ndata: 1\n\n'); } catch { clients.delete(c); } } }, 20000);

// ---------- API ----------
const handlers = {
  'POST /register'(b) {
    const deviceId = String(b.deviceId || '').slice(0, 100);
    const existing = deviceId && state.players.find(p => p.deviceId === deviceId);
    if (existing) { releaseSession(existing.id); touch(existing.id); save(); return { player: pub(existing), token: existing.token, existing: true, seq: evSeq, state: snapshot() }; }
    const name = String(b.name || '').trim().slice(0, 20);
    if (!name) throw fail(400, 'Name fehlt.');
    if (state.finished) throw fail(409, 'Das Event ist bereits beendet.');
    if (state.players.length >= MAX_PLAYERS) throw fail(409, 'Maximal 20 Spieler.');
    const taken = new Set(state.players.map(p => p.charId));
    let ci = CHARS.findIndex((_, i) => !taken.has(i)); if (ci < 0) ci = randInt(CHARS.length);
    const p = { id: uid('p'), token: secret(), deviceId, name, avatar: CHARS[ci][0], charName: CHARS[ci][1], charId: ci, score: 0, soloGames: [], duelGames: [], played: [] };
    state.players.push(p); touch(p.id);
    if (!state.hostId) state.hostId = p.id;     // erster Spieler = Spielleiter
    save(); broadcast();
    return { player: pub(p), token: p.token, seq: evSeq, state: snapshot() };
  },
  'POST /resume'(b) {                           // Seite neu geladen → wieder einloggen
    const deviceId = String(b.deviceId || '').slice(0, 100);
    const p = deviceId && state.players.find(x => x.deviceId === deviceId);
    if (!p) throw fail(200, 'Unbekanntes Gerät.');   // 200 + ok:false, damit der Erstbesuch keinen Browser-Fehler erzeugt
    releaseSession(p.id); touch(p.id); save(); broadcast();
    return { player: pub(p), token: p.token, seq: evSeq, state: snapshot() };
  },
  'POST /duels/draw'(b) {                       // Zufallsgegner ziehen (ohne Nebenwirkung; erst /duels/request verschickt die Herausforderung)
    const me = auth(b), g = String(b.gameId || '');
    if (!GAME_IDS.includes(g)) throw fail(400, 'Unbekanntes Spiel.');
    if (state.finished) throw fail(409, 'Event beendet.');
    if (me.duelGames.includes(g)) throw fail(409, 'Du hast dieses Spiel schon als Duell gespielt.');
    if (busyDuel(me.id)) throw fail(409, 'Du hast schon ein offenes Duell.');
    const exclude = Array.isArray(b.exclude) ? b.exclude.map(String).slice(0, 40) : [];
    let c = candidatesFor(me, g, exclude);
    if (!c.length && exclude.length) c = candidatesFor(me, g, []);   // alle schon gesehen → von vorn
    if (!c.length) throw fail(409, 'Gerade ist niemand für dieses Duell frei.');
    const pick = c[randInt(c.length)];
    return { candidate: pub(pick), pool: c.map(o => ({ id: o.id, name: o.name, avatar: o.avatar })) };
  },
  'POST /duels/request'(b) {
    const from = auth(b), to = getPlayer(String(b.toId || '')), g = String(b.gameId || '');
    if (!to || to.id === from.id) throw fail(400, 'Ungültiger Gegner.');
    if (!GAME_IDS.includes(g)) throw fail(400, 'Unbekanntes Spiel.');
    if (state.finished) throw fail(409, 'Event beendet.');
    if (from.duelGames.includes(g)) throw fail(409, 'Du hast dieses Spiel schon als Duell gespielt.');
    if (to.duelGames.includes(g)) throw fail(409, `${to.name} hat dieses Duell schon gespielt. Bitte neu würfeln.`);
    if (busyDuel(from.id)) throw fail(409, 'Du hast schon ein offenes Duell.');
    if (busyDuel(to.id)) throw fail(409, `${to.name} ist gerade in einem Duell. Bitte neu würfeln.`);
    const d = { id: uid('d'), gameId: g, fromId: from.id, toId: to.id, status: 'pending', createdAt: Date.now(), seed: randInt(2 ** 31), scores: {}, resulted: false };
    state.duels[d.id] = d; save();
    pushPlayer(to.id, 'duel:incoming', { id: d.id, gameId: d.gameId, fromId: d.fromId, toId: d.toId, status: d.status });
    broadcast();
    return { duel: { id: d.id }, state: snapshot() };
  },
  'POST /duels/respond'(b) {
    const p = auth(b), d = state.duels[String(b.duelId || '')];
    if (!d || d.toId !== p.id) throw fail(404, 'Herausforderung nicht gefunden.');
    if (d.status !== 'pending') throw fail(409, 'Herausforderung ist nicht mehr offen.');
    if (Date.now() - d.createdAt > PENDING_TTL) { d.status = 'expired'; save(); throw fail(409, 'Herausforderung ist abgelaufen.'); }
    const pub_ = { id: d.id, gameId: d.gameId, fromId: d.fromId, toId: d.toId };
    if (!b.accept) { d.status = 'declined'; save(); pushPlayer(d.fromId, 'duel:declined', { ...pub_, status: d.status }); broadcast(); return { duel: { ...pub_, status: d.status }, state: snapshot() }; }
    if (state.finished) throw fail(409, 'Event beendet.');
    const from = getPlayer(d.fromId);
    if (p.duelGames.includes(d.gameId) || (from && from.duelGames.includes(d.gameId))) { d.status = 'cancelled'; save(); throw fail(409, 'Dieses Duell wurde inzwischen gespielt.'); }
    releaseSession(d.fromId); releaseSession(d.toId);
    d.status = 'accepted'; d.acceptedAt = Date.now();
    p.duelGames.push(d.gameId); if (from) from.duelGames.push(d.gameId);
    save();
    const out = { ...pub_, status: d.status, seed: d.seed };
    pushPlayer(d.fromId, 'duel:accepted', out); pushPlayer(d.toId, 'duel:accepted', out);
    broadcast();
    return { duel: out, state: snapshot() };
  },
  'POST /duels/cancel'(b) {
    const p = auth(b), d = state.duels[String(b.duelId || '')];
    if (d && d.fromId === p.id && d.status === 'pending') { d.status = 'cancelled'; save(); pushPlayer(d.toId, 'duel:withdrawn', { id: d.id }); broadcast(); }
    return { state: snapshot() };
  },
  'POST /poll'(b) {                               // Fallback, falls SSE von einem Proxy gestört wird
    const p = auth(b);
    const after = Number(b.after);
    const events = Number.isFinite(after) && after > 0 ? (inbox.get(p.id) || []).filter(e => e.id > after).map(({ id, event, data }) => ({ id, event, data })) : [];
    return { seq: evSeq, events, state: snapshot() };
  },
  'POST /game/start'(b) {                         // Solo-Spiel
    const p = auth(b), g = String(b.gameId || '');
    if (!GAME_IDS.includes(g)) throw fail(400, 'Unbekanntes Spiel.');
    if (state.finished) throw fail(409, 'Event beendet.');
    releaseSession(p.id);
    if (p.soloGames.includes(g)) throw fail(409, 'Dieses Spiel hast du solo schon gespielt.');
    p.soloGames.push(g); state.sessions[p.id] = { gameId: g, at: Date.now(), seed: randInt(2 ** 31) }; save(); broadcast();
    return { seed: state.sessions[p.id].seed, state: snapshot() };
  },
  'POST /game/finish'(b) {
    const p = auth(b), g = String(b.gameId || '');
    if (!GAME_IDS.includes(g)) throw fail(400, 'Ungültiges Ergebnis.');
    if (b.duelId) {
      const d = openDuelFor(p, String(b.duelId));
      if (!d || d.gameId !== g) return { already: true, state: snapshot() };
      if (d.scores[p.id] !== undefined) return d.resulted ? { result: d.result, state: snapshot() } : { pending: true, state: snapshot() };
      submitDuel(d, p, b.points, false); save(); broadcast();
      return d.resulted ? { result: d.result, state: snapshot() } : { pending: true, state: snapshot() };
    }
    const s = state.sessions[p.id];
    if (!s || s.gameId !== g) throw fail(409, 'Kein laufendes Spiel – Ergebnis nicht gewertet.');
    delete state.sessions[p.id];
    const pts = clamp(b.points);
    addScore(p, g, pts, 'solo'); save(); broadcast();
    return { points: pts, state: snapshot() };
  },
  'POST /game/cancel'(b) {
    const p = auth(b);
    if (b.duelId) {
      const d = openDuelFor(p, String(b.duelId));
      if (d) { submitDuel(d, p, 0, true); save(); broadcast(); if (d.resulted) return { result: d.result, state: snapshot() }; }
    } else { releaseSession(p.id); save(); broadcast(); }
    return { state: snapshot() };
  },
  'POST /event/end'(b) {
    const p = auth(b);
    if (p.id !== state.hostId) throw fail(403, 'Nur der Spielleiter darf das Event beenden.');
    state.finished = true; save(); broadcast(); return { state: snapshot() };
  },
  'POST /event/reset'(b) {
    const p = auth(b);
    if (p.id !== state.hostId) throw fail(403, 'Nur der Spielleiter darf zurücksetzen.');
    state = empty(); save(); broadcast(); return { state: snapshot() };
  },
};

function readBody(req) {
  return new Promise((resolve, reject) => {
    let s = '', size = 0;
    req.on('data', c => { size += c.length; if (size > 100000) { req.destroy(); return reject(fail(413, 'Anfrage zu groß')); } s += c; });
    req.on('end', () => { if (!s) return resolve({}); try { resolve(JSON.parse(s)); } catch { reject(fail(400, 'Ungültiges JSON')); } });
    req.on('error', reject);
  });
}
function sendJSON(res, status, obj) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(obj));
}
async function api(req, res, route) {
  try {
    if (req.method === 'GET' && route === '/state') return sendJSON(res, 200, { ok: true, state: snapshot() });
    if (req.method === 'GET' && route === '/health') return sendJSON(res, 200, { ok: true, players: state.players.length, finished: state.finished });
    const h = handlers[`${req.method} ${route}`];
    if (!h) return sendJSON(res, req.method === 'POST' || req.method === 'GET' ? 404 : 405, { ok: false, error: 'Unbekannter Endpunkt' });
    const out = h(await readBody(req));
    sendJSON(res, 200, { ok: true, ...out });
  } catch (e) {
    if (!e.status) console.error(e);
    sendJSON(res, e.status || 500, { ok: false, error: e.status ? e.message : 'Serverfehler' });
  }
}
function serve(res, file, type) {
  try { const b = EMBED[path.basename(file)] !== undefined ? Buffer.from(EMBED[path.basename(file)]) : fs.readFileSync(file); res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-store' }); res.end(b); }
  catch { res.writeHead(404); res.end('Not found'); }
}

const STATIC = { '/games.js': 'application/javascript; charset=utf-8', '/app.js': 'application/javascript; charset=utf-8', '/style.css': 'text/css; charset=utf-8' };
const server = http.createServer((req, res) => {
  const u = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (u.pathname === '/events' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache, no-transform', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no' });
    res.write(`retry: 2000\nevent: state\ndata: ${JSON.stringify(snapshot())}\n\n`);
    const c = { res, playerId: u.searchParams.get('playerId') || '' };
    const last = Number(req.headers['last-event-id']);
    if (Number.isFinite(last) && last > 0 && c.playerId) for (const e of (inbox.get(c.playerId) || [])) if (e.id > last) res.write(`id: ${e.id}\nevent: ${e.event}\ndata: ${JSON.stringify(e.data)}\n\n`);
    clients.add(c); req.on('close', () => clients.delete(c));
    return;
  }
  if (u.pathname.startsWith('/api/')) return api(req, res, u.pathname.slice(4));
  if (u.pathname === '/' || u.pathname === '/index.html') return serve(res, path.join(PUBLIC, 'index.html'), 'text/html; charset=utf-8');
  if (u.pathname === '/favicon.ico') { res.writeHead(204); return res.end(); }
  const st = STATIC[u.pathname];
  if (st) return serve(res, path.join(PUBLIC, u.pathname.slice(1)), st);
  res.writeHead(404); res.end('Not found');
});
loadRemote().finally(() => server.listen(PORT, () => console.log(`Wiesn Team Challenge: http://localhost:${PORT} · Speicher: Datei${USE_REDIS ? ' + Redis' : ''}`)));

for (const sig of ['SIGTERM', 'SIGINT']) process.on(sig, async () => { save(); try { await Promise.race([flushRemote(), new Promise(r => setTimeout(r, 3000))]); } catch {} server.close(); process.exit(0); });
